-- ============================================================================
-- Kolis baseline schema migration (MCP-generated)
-- ----------------------------------------------------------------------------
-- This file is a baseline snapshot of the Kolis application's schema captured
-- from the live Supabase Postgres project (kzjptcpjpwlxfofzhyku) on 2026-07-21.
--
-- It was generated by querying the Postgres catalogs directly through the
-- Supabase MCP tools, because Docker / pg_dump were unavailable in the
-- environment where this baseline was produced.
--
-- Scope: ONLY Kolis-owned objects in schema `public` whose names start with
--   `kolis_` or `concord_`. This database is shared with the LoadQ app; all
--   LoadQ-owned and other non-Kolis objects are intentionally EXCLUDED.
--
-- APPLY ORDER / EXTERNAL DEPENDENCIES (important): this baseline is NOT
--   standalone. Because Kolis and LoadQ share one database, some Kolis objects
--   reference LoadQ / Supabase-managed objects that must already exist:
--     * FKs: kolis_parcels.pickup_zone -> zones(id), kolis_zone_settings.zone_id
--       -> zones(id), kolis_profiles.loadq_driver_id -> drivers(id)  [LoadQ]
--     * RLS policies on kolis_driver_payout/hubs/parcels/zone_settings read the
--       LoadQ `drivers` table (drivers.is_admin)
--     * Many FKs reference auth.users(id)  [Supabase auth schema]
--     * Extensions live in non-public schemas (extensions, pg_catalog, vault)
--   To provision a fresh environment: create the Supabase `auth` schema +
--   extensions (default on any Supabase project), apply LoadQ's schema first
--   (for `zones`/`drivers`), THEN this baseline. On the existing prod DB it is
--   already satisfied and is recorded as applied (never re-run).
--
-- Predecessor migrations (the divergent pre-baseline local files) were moved to
--   supabase/migrations_archive/ for reference; they are superseded by this file.
--
-- Section order (pg_dump-style, so it applies cleanly on a fresh database):
--   1. Extensions
--   2. Tables (columns only, no constraints)
--   3. Sequences
--   4. Functions
--   5. Views
--   6. Indexes (non-constraint-backing)
--   7. Constraints (PK / UNIQUE / FK / CHECK)
--   8. Triggers
--   9. Row Level Security (enable + policies)
--  10. Grants
-- ============================================================================


-- ============================================================================
-- 1. EXTENSIONS
-- ============================================================================
create extension if not exists pg_cron with schema pg_catalog;
create extension if not exists pg_net with schema extensions;
create extension if not exists pg_stat_statements with schema extensions;
create extension if not exists pgcrypto with schema extensions;
create extension if not exists supabase_vault with schema vault;
create extension if not exists "uuid-ossp" with schema extensions;


-- ============================================================================
-- 2. TABLES (columns only; constraints added in section 7)
-- ============================================================================
