CREATE OR REPLACE FUNCTION public.concord_next_due(p_initial timestamp with time zone, p_touch integer)
 RETURNS timestamp with time zone
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case p_touch
    when 0 then p_initial + interval '4 days'
    when 1 then p_initial + interval '10 days'
    when 2 then p_initial + interval '18 days'
    else null end;
$function$
;

CREATE OR REPLACE FUNCTION public.concord_outreach_add(p_name text, p_email text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  insert into public.concord_outreach(business_name, email, initial_sent_at, last_sent_at, touch_count, next_due_at, status)
    values (p_name, lower(p_email), now(), now(), 0, public.concord_next_due(now(),0), 'active')
  on conflict (email) do update set business_name = excluded.business_name
  returning id into v_id;
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.concord_outreach_dashboard()
 RETURNS TABLE(business_name text, email text, status text, touch_count integer, initial_sent_at timestamp with time zone, last_sent_at timestamp with time zone, next_due_at timestamp with time zone, opened_at timestamp with time zone, clicked_at timestamp with time zone, bounced_at timestamp with time zone, opens bigint, clicks bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not coalesce(public.kolis_is_staff(), false) then raise exception 'forbidden'; end if;
  return query
    select o.business_name, o.email, o.status, o.touch_count, o.initial_sent_at, o.last_sent_at, o.next_due_at,
      o.opened_at, o.clicked_at, o.bounced_at,
      (select count(*) from public.concord_outreach_events e where e.email = o.email and e.type = 'opened'),
      (select count(*) from public.concord_outreach_events e where e.email = o.email and e.type = 'clicked')
    from public.concord_outreach o order by o.created_at desc;
end; $function$
;

CREATE OR REPLACE FUNCTION public.concord_outreach_set_status(p_email text, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not coalesce(public.kolis_is_staff(), false) then raise exception 'forbidden'; end if;
  if p_status not in ('active','replied','stopped','done') then raise exception 'bad status'; end if;
  update public.concord_outreach
    set status = p_status, next_due_at = case when p_status = 'active' then next_due_at else null end
    where email = lower(p_email);
end; $function$
;

CREATE OR REPLACE FUNCTION public.concord_outreach_status()
 RETURNS SETOF concord_outreach
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from public.concord_outreach order by created_at desc;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_accept_org_invite()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count int := 0; r record;
begin
  for r in select i.* from public.kolis_org_invites i
    where i.accepted_at is null and lower(i.email) in (
      select lower(e) from (
        select (select email from auth.users where id=auth.uid()) as e
        union all select (select email from public.kolis_profiles where id=auth.uid())) s where s.e is not null)
  loop
    insert into public.kolis_org_members(org_id, user_id, role, full_name)
    values (r.org_id, auth.uid(), r.role, r.full_name)
    on conflict (org_id, user_id) do update set role=excluded.role,
      full_name = coalesce(public.kolis_org_members.full_name, excluded.full_name);
    update public.kolis_org_invites set accepted_at=now() where id=r.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_accept_parcel(p_id uuid, p_via text DEFAULT NULL::text, p_eta_minutes integer DEFAULT NULL::integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_kp uuid; v_loadq uuid;
begin
  select kp.id, coalesce(kp.loadq_driver_id, kp.id) into v_kp, v_loadq
  from public.kolis_profiles kp
  where (kp.id = auth.uid() or kp.loadq_driver_id = auth.uid())
    and kp.identity_verified and kp.role in ('courier','both')
  order by (kp.id = auth.uid()) desc limit 1;
  if v_kp is null then return false; end if;

  if (select count(*) from public.kolis_parcels
      where driver_id = v_kp and status in ('matched','picked_up','in_transit')) >= 3 then
    return false;
  end if;

  update public.kolis_parcels p
    set driver_id = v_kp, status = 'matched', preferred_driver_id = null, offer_expires_at = null,
        accepted_via = coalesce(p_via, p.accepted_via),
        pickup_eta_minutes = p_eta_minutes,
        pickup_eta_at = case when p_eta_minutes is not null then now() + make_interval(mins => p_eta_minutes) else null end
  where p.id = p_id and p.driver_id is null
    and p.sender_id <> v_kp
    and p.status in ('requested','received_at_hub')
    and (
      (p.preferred_driver_id = v_kp and p.offer_expires_at > now())
      or
      ( not (p.preferred_driver_id is not null and p.preferred_driver_id <> v_kp
             and p.offer_expires_at is not null and p.offer_expires_at > now())
        and (
          exists (select 1 from public.queue_entries q
                  where q.driver_id = v_loadq and q.destination_region = p.to_region and q.end_reason is null
                    and (p.dropoff_type = 'hub' or coalesce(q.position,1) >= 2))
          or
          (p.dropoff_type = 'door'
            and not exists (select 1 from public.queue_entries q3 where q3.driver_id = v_loadq and q3.end_reason is null))
        )
      )
    );
  return found;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_activate_founding()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text; v_verified boolean; v_paid boolean; v_fn int; n int;
begin
  select role, identity_verified, verification_fee_paid, founding_number
    into v_role, v_verified, v_paid, v_fn
    from public.kolis_profiles where id = auth.uid();
  if v_role is null then raise exception 'no_profile'; end if;
  if coalesce(v_paid, false) then return jsonb_build_object('ok', true, 'founding_number', v_fn); end if;
  if not coalesce(v_verified, false) then raise exception 'verify_identity_first'; end if;
  update public.kolis_founding set count = count + 1
    where role = v_role and count < 100 returning count into n;
  if n is null then return jsonb_build_object('founding', false); end if; -- cap reached → must pay
  update public.kolis_profiles
    set is_founding = true, founding_number = n, verification_fee_paid = true
    where id = auth.uid();
  return jsonb_build_object('ok', true, 'founding_number', n);
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_all_caps()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
AS $function$ select array['orgs','parcels','claims','members','revenue']::text[] $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_assign(p_id uuid, p_driver uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.kolis_admin_has_cap('parcels') then
    raise exception 'forbidden';
  end if;
  update public.kolis_parcels
     set preferred_driver_id = p_driver,
         offer_expires_at    = now() + interval '60 minutes',
         driver_id           = null,
         status              = case when dropoff_type = 'hub' then 'received_at_hub' else 'requested' end
   where id = p_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_assign_direct(p_id uuid, p_driver uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.kolis_admin_has_cap('parcels') then raise exception 'forbidden'; end if;
  update public.kolis_parcels
     set driver_id = p_driver,
         preferred_driver_id = p_driver,
         offer_expires_at = null,
         status = case when status in ('requested','received_at_hub') then 'matched' else status end
   where id = p_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_cancel_invite(p_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_admin_role(),'') <> 'owner' then raise exception 'forbidden'; end if;
  delete from public.kolis_admin_invites where lower(email) = lower(p_email);
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_candidates(p_id uuid)
 RETURNS TABLE(driver_id uuid, name text, queue_pos integer, carrying integer, source text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with target as (select to_region from public.kolis_parcels where id = p_id)
  select pr.id,
         coalesce(nullif(btrim(d.full_name), ''), pr.full_name) as name,
         q.position as queue_pos,
         (select count(*) from public.kolis_parcels c
            where c.driver_id = pr.id and c.status in ('matched','dispatched','picked_up','in_transit'))::int as carrying,
         case when q.driver_id is not null then 'queue' else 'member' end as source
  from public.kolis_profiles pr
  left join public.drivers d on d.id = coalesce(pr.loadq_driver_id, pr.id)
  left join public.queue_entries q
         on q.driver_id = coalesce(pr.loadq_driver_id, pr.id)
        and q.end_reason is null and q.status in ('waiting','loading','standby')
  where public.kolis_admin_has_cap('parcels')
    and pr.identity_verified
    and pr.role in ('courier','both')
  order by
    (q.driver_id is null),                                                     -- on the queue first (any destination)
    (q.destination_region is distinct from (select to_region from target)),    -- among those, heading-to-destination first
    q.position nulls last
  limit 60;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_caps()
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_caps text[];
begin
  if public.kolis_admin_role() is null then return '{}'; end if;
  if public.kolis_admin_role() = 'owner' then return public.kolis_admin_all_caps(); end if;
  select capabilities into v_caps from public.kolis_admin_roles where user_id = auth.uid();
  return coalesce(v_caps, '{}');
end; $function$
;

