AS $function$
begin
  if not public.kolis_admin_has_cap('parcels') then raise exception 'forbidden'; end if;
  update public.kolis_parcels set driver_id = p_driver where id = p_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_claims(p_status text DEFAULT 'open'::text)
 RETURNS TABLE(id uuid, parcel_id uuid, code text, from_city text, to_city text, type text, status text, insured boolean, declared_value_cents integer, price_cents integer, refund_cents integer, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select c.id, c.parcel_id, p.code, p.from_city, p.to_city, c.type, c.status,
         p.insured, p.declared_value_cents, p.price_cents, c.refund_cents, c.created_at
  from public.kolis_claims c join public.kolis_parcels p on p.id = c.parcel_id,
       (select public.kolis_admin_has_cap('claims') s) g
  where g.s and (p_status='all' or c.status = p_status)
  order by c.created_at desc limit 200;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_contact_requests()
 RETURNS TABLE(id uuid, user_id uuid, name text, current_email text, current_phone text, requested_email text, requested_phone text, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select r.id, r.user_id, coalesce(pr.verified_name, pr.full_name), r.current_email, r.current_phone, r.requested_email, r.requested_phone, r.created_at
  from public.kolis_contact_requests r left join public.kolis_profiles pr on pr.id = r.user_id
  where r.status = 'pending' and public.kolis_admin_has_cap('members')
  order by r.created_at;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_create_key(p_name text, p_scopes text[] DEFAULT '{read_parcels}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_key text; v_prefix text;
begin
  if coalesce(public.kolis_admin_role(),'') <> 'owner' then raise exception 'forbidden'; end if;
  v_key := 'kls_live_' || encode(gen_random_bytes(24), 'hex');
  v_prefix := left(v_key, 16);
  insert into public.kolis_access_keys(name, prefix, key_hash, scopes, created_by)
  values (p_name, v_prefix, encode(digest(v_key, 'sha256'), 'hex'), p_scopes, auth.uid());
  return jsonb_build_object('key', v_key, 'prefix', v_prefix);  -- shown once
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_create_org(p_name text, p_type text, p_billing_email text DEFAULT NULL::text, p_net_terms integer DEFAULT 30, p_discount numeric DEFAULT 0, p_credit_limit_cents bigint DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if coalesce(public.kolis_admin_role(),'') not in ('owner','admin') then raise exception 'forbidden'; end if;
  if p_type not in ('shipper','carrier','both') then raise exception 'bad_type'; end if;
  insert into public.kolis_orgs(name, type, billing_email, net_terms_days, discount_rate, credit_limit_cents)
  values (p_name, p_type, p_billing_email, coalesce(p_net_terms,30), coalesce(p_discount,0), coalesce(p_credit_limit_cents,0))
  returning id into v_id;
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_dead_notifications()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.kolis_is_staff() then raise exception 'forbidden'; end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', n.id, 'kind', n.kind, 'state', n.state, 'attempts', n.attempts,
      'last_error', n.last_error, 'created_at', n.created_at, 'last_attempt_at', n.last_attempt_at,
      'code', p.code, 'recipient_name', p.recipient_name, 'recipient_phone', p.recipient_phone,
      'recipient_email', p.recipient_email, 'parcel_status', p.status
    ) order by n.last_attempt_at desc nulls last), '[]'::jsonb)
    from public.kolis_notifications n join public.kolis_parcels p on p.id = n.parcel_id
    where n.state = 'dead'
  );
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_has_cap(p_cap text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select p_cap = any(public.kolis_admin_caps()) $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_invite(p_email text, p_role text, p_caps text[] DEFAULT '{}'::text[])
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid;
begin
  if coalesce(public.kolis_admin_role(),'') <> 'owner' then raise exception 'forbidden'; end if;
  if p_role not in ('admin','dispatcher','finance','support') then raise exception 'bad role'; end if;
  select id into v_uid from public.kolis_profiles where lower(email) = lower(p_email) limit 1;
  if v_uid is not null then
    insert into public.kolis_admin_roles(user_id, role, capabilities, invited_email, invited_by)
    values (v_uid, p_role, coalesce(p_caps,'{}'), p_email, auth.uid())
    on conflict (user_id) do update set role = excluded.role, capabilities = excluded.capabilities;
    return 'granted';
  else
    insert into public.kolis_admin_invites(email, role, capabilities, invited_by)
    values (lower(p_email), p_role, coalesce(p_caps,'{}'), auth.uid())
    on conflict (email) do update set role = excluded.role, capabilities = excluded.capabilities;
    return 'pending';
  end if;
end; $function$
;

