CREATE OR REPLACE FUNCTION public.kolis_admin_members(p_filter text DEFAULT 'all'::text, p_search text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, full_name text, email text, role text, country text, identity_verified boolean, is_founding boolean, founding_number integer, suspended boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select pr.id, coalesce(pr.verified_name, pr.full_name), pr.email, pr.role, pr.country,
         pr.identity_verified, pr.is_founding, pr.founding_number, pr.suspended
  from public.kolis_profiles pr, (select public.kolis_admin_has_cap('members') s) g
  where g.s and (
        p_filter='all'
     or (p_filter='couriers'   and pr.role in ('courier','both'))
     or (p_filter='senders'    and pr.role in ('sender','both'))
     or (p_filter='unverified' and not pr.identity_verified)
     or (p_filter='founding'   and pr.is_founding))
    and (p_search is null or p_search='' or coalesce(pr.full_name,'') ilike '%'||p_search||'%'
         or coalesce(pr.email,'') ilike '%'||p_search||'%')
  order by pr.founding_number nulls last limit 200;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_org(p_org uuid)
 RETURNS SETOF kolis_orgs
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select o.* from public.kolis_orgs o where public.kolis_is_staff() and o.id = p_org;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_org_add_member_by_phone(p_org uuid, p_phone text, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid; v_digits text; v_name text;
begin
  if coalesce(public.kolis_admin_role(),'') not in ('owner','admin') then raise exception 'forbidden'; end if;
  if p_role not in ('owner','admin','finance','shipper','dispatcher','driver') then raise exception 'bad_role'; end if;
  v_digits := regexp_replace(coalesce(p_phone,''), '\D', '', 'g');
  if v_digits = '' then raise exception 'bad_phone'; end if;
  -- auth.users.phone is E.164 without '+', e.g. 16138622639. Accept 10- or 11-digit input.
  select id into v_uid from auth.users
   where phone = v_digits or phone = '1' || v_digits or '1' || phone = v_digits
   limit 1;
  if v_uid is null then raise exception 'no_account_for_phone'; end if;
  insert into public.kolis_org_members(org_id, user_id, role)
  values (p_org, v_uid, p_role)
  on conflict (org_id, user_id) do update set role = excluded.role;
  select full_name into v_name from public.kolis_profiles where id = v_uid;
  return jsonb_build_object('user_id', v_uid, 'full_name', coalesce(v_name, '(no profile yet)'));
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_org_invite(p_org uuid, p_email text, p_role text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if coalesce(public.kolis_admin_role(),'') not in ('owner','admin') then raise exception 'forbidden'; end if;
  if p_role not in ('owner','admin','finance','shipper','dispatcher','driver') then raise exception 'bad_role'; end if;
  insert into public.kolis_org_invites(org_id, email, role, invited_by)
  values (p_org, lower(trim(p_email)), p_role, auth.uid())
  on conflict (org_id, lower(email)) do update set role = excluded.role, accepted_at = null, invited_by = auth.uid()
  returning id into v_id;
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_org_members(p_org uuid)
 RETURNS TABLE(user_id uuid, role text, full_name text, email text, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select m.user_id, m.role,
    coalesce(nullif(m.full_name,''), nullif(p.full_name,''), au.raw_user_meta_data->>'full_name',
             au.raw_user_meta_data->>'name', initcap(replace(split_part(au.email,'@',1),'.',' '))) as full_name,
    coalesce(nullif(p.email,''), au.email) as email, m.created_at
  from public.kolis_org_members m
  left join public.kolis_profiles p on p.id=m.user_id
  left join auth.users au on au.id=m.user_id
  where public.kolis_is_staff() and m.org_id=p_org order by m.created_at;
$function$
;

