CREATE OR REPLACE FUNCTION public.kolis_admin_set_org_limits(p_org uuid, p_credit_limit_cents bigint DEFAULT NULL::bigint, p_discount numeric DEFAULT NULL::numeric, p_net_terms integer DEFAULT NULL::integer, p_platform_fee numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_admin_role(),'') not in ('owner','admin','finance') then raise exception 'forbidden'; end if;
  update public.kolis_orgs set
    credit_limit_cents = coalesce(p_credit_limit_cents, credit_limit_cents),
    discount_rate      = coalesce(p_discount, discount_rate),
    net_terms_days     = coalesce(p_net_terms, net_terms_days),
    platform_fee_rate  = coalesce(p_platform_fee, platform_fee_rate)
  where id = p_org;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_set_org_profile(p_org uuid, p_name text DEFAULT NULL::text, p_billing_email text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.kolis_admin_has_cap('orgs') then raise exception 'forbidden'; end if;
  update public.kolis_orgs set
    name = coalesce(nullif(trim(p_name), ''), name),                -- never blank the name
    billing_email = case when p_billing_email is null then billing_email else nullif(trim(p_billing_email), '') end
  where id = p_org;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_set_org_status(p_org uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
