 SET search_path TO 'public'
AS $function$
begin
  if not public.kolis_admin_has_cap('orgs') then raise exception 'forbidden'; end if;
  if p_status not in ('active','suspended') then raise exception 'bad_status'; end if;
  update public.kolis_orgs set status = p_status where id = p_org;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_shopify_shops()
 RETURNS TABLE(shop_domain text, shop_name text, shop_email text, org_id uuid, org_name text, installed_at timestamp with time zone, uninstalled_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
