CREATE OR REPLACE FUNCTION public.kolis_admin_suspend(p_id uuid, p_suspended boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.kolis_admin_has_cap('members') then raise exception 'forbidden'; end if;
  update public.kolis_profiles set suspended = p_suspended where id = p_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_team()
 RETURNS TABLE(user_id uuid, name text, email text, role text, pending boolean, caps text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select r.user_id, coalesce(pr.verified_name, pr.full_name, d.full_name, r.invited_email), coalesce(pr.email, r.invited_email), r.role, false,
         case when r.role='owner' then public.kolis_admin_all_caps() else coalesce(r.capabilities,'{}') end
  from public.kolis_admin_roles r
  left join public.kolis_profiles pr on pr.id = r.user_id
  left join public.drivers d on d.id = r.user_id
  where public.kolis_admin_role() = 'owner'
  union all
  select d.id, d.full_name, null, 'owner', false, public.kolis_admin_all_caps()
  from public.drivers d
  where d.is_admin and public.kolis_admin_role() = 'owner'
    and not exists(select 1 from public.kolis_admin_roles r2 where r2.user_id = d.id)
  union all
  select null::uuid, i.email, i.email, i.role, true, coalesce(i.capabilities,'{}')
  from public.kolis_admin_invites i where public.kolis_admin_role() = 'owner';
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_admin_unassign(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.kolis_admin_has_cap('parcels') then raise exception 'forbidden'; end if;
  update public.kolis_parcels
     set driver_id = null, preferred_driver_id = null, offer_expires_at = null,
         status = case when dropoff_type='hub' then 'received_at_hub' else 'requested' end
   where id = p_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_api_create_shipment(p_org uuid, p_sender uuid, p_dropoff_type text, p_size text, p_from_city text, p_to_city text, p_recipient_name text, p_recipient_phone text, p_dropoff_addr text, p_client_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_code text; v_price int; v_status text; v_sender uuid;
begin
  if (select status from public.kolis_orgs where id = p_org) <> 'active' then raise exception 'org_inactive'; end if;
  if p_dropoff_type not in ('door','zone','hub') then raise exception 'bad_dropoff'; end if;
  if p_size not in ('envelope','small','large') then raise exception 'bad_size'; end if;
  v_sender := coalesce(p_sender, (select user_id from public.kolis_org_members where org_id=p_org and role in ('owner','admin') order by role limit 1));

  if p_client_ref is not null then
    select id, code into v_id, v_code from public.kolis_parcels where org_id = p_org and client_ref = p_client_ref;
    if v_id is not null then return jsonb_build_object('id',v_id,'code',v_code,'dedup',true); end if;
  end if;

  v_price := public.kolis_estimate_price_cents(p_size, p_dropoff_type, p_from_city, p_to_city);
  perform public.kolis_check_credit(p_org, v_price);
  v_status := case when p_dropoff_type = 'hub' then 'received_at_hub' else 'requested' end;

  insert into public.kolis_parcels(
    code, sender_id, status, dropoff_type, size, from_city, to_city, to_region,
    price_cents, driver_payout_cents, billing_mode, org_id, client_ref,
    recipient_name, recipient_phone, dropoff_addr)
  values (
    public.kolis_gen_parcel_code(), v_sender, v_status, p_dropoff_type, p_size, p_from_city, p_to_city,
    public.kolis_region_code(p_to_city),
    v_price, public.kolis_driver_payout_cents(v_price, p_dropoff_type), 'invoice', p_org, p_client_ref,
    p_recipient_name, p_recipient_phone, p_dropoff_addr)
  returning id, code into v_id, v_code;
  return jsonb_build_object('id', v_id, 'code', v_code, 'price_cents', v_price, 'status', v_status);
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_apply_stripe_invoice_event(p_event_id text, p_stripe_invoice_id text, p_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rows int; v_org uuid;
begin
  insert into public.kolis_stripe_events(event_id) values (p_event_id) on conflict do nothing;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then return false; end if;          -- replay → already processed

  if p_status = 'paid' then
    update public.kolis_invoices set status='paid', paid_at=now()
      where stripe_invoice_id = p_stripe_invoice_id and status <> 'paid'
      returning org_id into v_org;
    if v_org is not null then
      update public.kolis_orgs set status='active' where id = v_org and status = 'suspended';
    end if;
  elsif p_status = 'payment_failed' then
    -- leave the invoice 'open'; Phase 3b's suspension job handles overdue.
    null;
  end if;
  return true;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_auth_user_by_email(p_email text)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select id from auth.users where lower(email) = lower(p_email) limit 1;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_available_drivers(p_zone_id text, p_dest_region text)
 RETURNS TABLE(driver_id uuid, display_name text, avatar_url text, trust_score integer, verified boolean, queue_position integer, seats_available integer, queued_minutes integer)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    qe.driver_id,
    coalesce(nullif(split_part(d.full_name, ' ', 1), ''), 'Driver')
      || case when length(split_part(d.full_name, ' ', 2)) > 0
              then ' ' || left(split_part(d.full_name, ' ', 2), 1) || '.'
              else '' end as display_name,
    d.avatar_url,
    d.trust_score,
    coalesce(d.verified, false) as verified,
    qe.position,
    greatest(0, coalesce(qe.seats_locked, 0) - coalesce(qe.seats_boarded, 0)) as seats_available,
    floor(extract(epoch from (now() - qe.joined_at)) / 60)::int as queued_minutes
  from public.queue_entries qe
  join public.drivers d on d.id = qe.driver_id
  where qe.destination_region = p_dest_region
    and (p_zone_id is null or qe.zone_id = p_zone_id)
    and qe.end_reason is null
    and coalesce(d.blocked, false) = false
  order by qe.position nulls last, qe.joined_at;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_available_parcels()
 RETURNS TABLE(id uuid, code text, size text, from_city text, to_city text, to_region text, dropoff_type text, pickup_zone text, pickup_hub_name text, pickup_area text, driver_payout_cents integer, is_request boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with me as (
    select kp.id as kp_id,
           coalesce(kp.loadq_driver_id, kp.id) as loadq_id,
           (kp.identity_verified and kp.role in ('courier','both')) as is_member
    from public.kolis_profiles kp
    where kp.id = auth.uid() or kp.loadq_driver_id = auth.uid()
    order by (kp.id = auth.uid()) desc
    limit 1
  )
  select p.id, p.code, p.size, p.from_city, p.to_city, p.to_region,
         p.dropoff_type, p.pickup_zone, h.name as pickup_hub_name,
         -- Privacy-safe pickup area shown BEFORE accept: hub name, else zone, else the
         -- neighbourhood/city after the street (hides exact number + unit), else city.
         coalesce(
           h.name,
           p.pickup_zone,
           case when p.pickup_addr is not null and position(',' in p.pickup_addr) > 0
                then nullif(btrim(substring(p.pickup_addr from position(',' in p.pickup_addr) + 1)), '')
                else null end,
           p.from_city
         ) as pickup_area,
         p.driver_payout_cents,
         (p.preferred_driver_id = me.kp_id and p.offer_expires_at > now()) as is_request
  from public.kolis_parcels p
  left join public.kolis_hubs h on h.id = p.pickup_hub,
       me
  where coalesce(me.is_member, false)
    and (select count(*) from public.kolis_parcels c
         where c.driver_id = me.kp_id and c.status in ('matched','picked_up','in_transit')) < 3
    and p.driver_id is null
    and p.sender_id <> me.kp_id
    and p.status in ('requested','received_at_hub')
    and (
      (p.preferred_driver_id = me.kp_id and p.offer_expires_at > now())
      or
      ( not (p.preferred_driver_id is not null and p.preferred_driver_id <> me.kp_id
             and p.offer_expires_at is not null and p.offer_expires_at > now())
        and (
          (p.dropoff_type = 'hub' and p.status = 'received_at_hub'
            and exists (select 1 from public.queue_entries q
                        where q.driver_id = me.loadq_id and q.destination_region = p.to_region and q.end_reason is null))
          or
          (p.dropoff_type = 'door' and p.status = 'requested'
            and exists (select 1 from public.queue_entries q
                        where q.driver_id = me.loadq_id and q.destination_region = p.to_region
                          and q.end_reason is null and coalesce(q.position, 1) >= 2))
          or
          (p.dropoff_type = 'door' and p.status = 'requested'
            and not exists (select 1 from public.queue_entries q3 where q3.driver_id = me.loadq_id and q3.end_reason is null)
            and not exists (select 1 from public.queue_entries q4
                            where q4.destination_region = p.to_region and q4.end_reason is null and coalesce(q4.position,1) >= 2))
        )
      )
    );
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_call_request_set_status(p_id uuid, p_status text)
 RETURNS kolis_call_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.kolis_call_requests;
begin
  if not public.kolis_is_staff() then raise exception 'forbidden'; end if;
  if p_status not in ('new','called','done') then raise exception 'bad status'; end if;
  update public.kolis_call_requests set status=p_status where id=p_id returning * into v;
  return v;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_call_requests_list(p_status text DEFAULT NULL::text)
 RETURNS SETOF kolis_call_requests
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from public.kolis_call_requests
  where public.kolis_is_staff()
    and (p_status is null or status = p_status)
  order by created_at desc
  limit 500;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_carrier_advance_status(p_org uuid, p_parcel uuid, p_to text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_cur text;
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin','dispatcher') then raise exception 'forbidden'; end if;
  select status into v_cur from public.kolis_parcels
   where id = p_parcel and carrier_org_id = p_org and billing_mode = 'invoice';
  if v_cur is null then raise exception 'not_found'; end if;
  if not ((v_cur='matched' and p_to='picked_up')
       or (v_cur='picked_up' and p_to='in_transit')
       or (v_cur='in_transit' and p_to='delivered')) then
    raise exception 'illegal_transition';
  end if;
  update public.kolis_parcels
     set status = p_to, delivered_at = case when p_to='delivered' then now() else delivered_at end
   where id = p_parcel and carrier_org_id = p_org;
  return found;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_carrier_assign(p_org uuid, p_parcel uuid, p_driver uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin','dispatcher') then raise exception 'forbidden'; end if;
  -- driver must be a member of this fleet AND a verified Kolis courier
  if not exists (select 1 from public.kolis_org_members where org_id = p_org and user_id = p_driver) then
    raise exception 'driver_not_in_fleet';
  end if;
  if not exists (select 1 from public.kolis_profiles where id = p_driver and identity_verified and role in ('courier','both')) then
    raise exception 'driver_not_verified';
  end if;
  update public.kolis_parcels
     set driver_id = p_driver, carrier_org_id = p_org, status = 'matched',
         preferred_driver_id = null, offer_expires_at = null
   where id = p_parcel and driver_id is null
     and status in ('requested','received_at_hub')
     and billing_mode = 'invoice'      -- card-mode parcels use the escrow/code flow
     and sender_id <> p_driver;        -- self-booking guard
  return found;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_carrier_dispatch_board(p_org uuid)
 RETURNS TABLE(id uuid, code text, size text, dropoff_type text, from_city text, to_city text, status text, driver_id uuid, driver_name text, driver_payout_cents integer, mine boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  return query
    select p.id,p.code,p.size,p.dropoff_type,p.from_city,p.to_city,p.status,p.driver_id,
           pr.full_name as driver_name, p.driver_payout_cents,
           (p.carrier_org_id = p_org) as mine
    from public.kolis_parcels p
    left join public.kolis_profiles pr on pr.id = p.driver_id
    -- the fleet's own parcels, plus the open invoice-mode pool it may claim.
    -- Personal card-mode parcels are NOT shown here — they deliver via the
    -- existing 4-digit-code escrow capture, never the carrier board.
    where p.carrier_org_id = p_org
       or (p.carrier_org_id is null and p.driver_id is null
           and p.status in ('requested','received_at_hub') and p.billing_mode = 'invoice')
    order by (p.carrier_org_id = p_org) desc, p.created_at desc;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_carrier_drivers(p_org uuid)
 RETURNS TABLE(user_id uuid, role text, full_name text, identity_verified boolean, kolis_role text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  return query
    select m.user_id, m.role, pr.full_name, coalesce(pr.identity_verified,false), pr.role
    from public.kolis_org_members m
    left join public.kolis_profiles pr on pr.id = m.user_id
    where m.org_id = p_org
    order by pr.full_name;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_carrier_pending_payouts(p_org uuid)
 RETURNS TABLE(driver_id uuid, driver_name text, parcels integer, gross_cents bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  return query
    select p.driver_id, pr.full_name, count(*)::int, sum(p.driver_payout_cents)::bigint
    from public.kolis_parcels p left join public.kolis_profiles pr on pr.id=p.driver_id
    where p.carrier_org_id=p_org and p.status='delivered' and p.driver_paid_at is null
    group by p.driver_id, pr.full_name;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_carrier_statement(p_org uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  select jsonb_build_object(
    'statement', to_jsonb(s),
    'lines', coalesce((select jsonb_agg(jsonb_build_object('driver_id',l.driver_id,'driver_name',pr.full_name,'parcels',l.parcels,'gross_cents',l.gross_cents) order by l.gross_cents desc)
                       from public.kolis_payout_statement_lines l left join public.kolis_profiles pr on pr.id=l.driver_id
                       where l.statement_id=s.id),'[]'::jsonb))
  into v from public.kolis_payout_statements s where s.id=p_id and s.org_id=p_org;
  if v is null then raise exception 'not_found'; end if;
  return v;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_carrying()
 RETURNS TABLE(id uuid, code text, size text, from_city text, to_city text, to_region text, dropoff_type text, pickup_zone text, pickup_hub_name text, pickup_addr text, dropoff_addr text, recipient_name text, recipient_phone text, driver_payout_cents integer, status text, accepted_via text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with me as (
    select coalesce((select kp.id from public.kolis_profiles kp
                     where kp.id = auth.uid() or kp.loadq_driver_id = auth.uid()
                     order by (kp.id = auth.uid()) desc limit 1), auth.uid()) as kp_id
  )
  select p.id, p.code, p.size, p.from_city, p.to_city, p.to_region,
         p.dropoff_type, p.pickup_zone, h.name as pickup_hub_name, p.pickup_addr,
         case when p.status <> 'matched' then p.dropoff_addr end as dropoff_addr,
         case when p.status <> 'matched' then p.recipient_name end as recipient_name,
         case when p.status <> 'matched' then p.recipient_phone end as recipient_phone,
         p.driver_payout_cents, p.status, p.accepted_via
  from public.kolis_parcels p
  left join public.kolis_hubs h on h.id = p.pickup_hub, me
  where p.driver_id = me.kp_id
    and p.status in ('matched','picked_up','in_transit')
  order by p.created_at asc;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_check_credit(p_org uuid, p_add_cents bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_lim bigint; v_status text; v_out bigint;
begin
  select credit_limit_cents, status into v_lim, v_status from public.kolis_orgs where id = p_org for update;
  if v_status is null then raise exception 'org_not_found'; end if;
  if v_status <> 'active' then raise exception 'org_suspended'; end if;
  v_out := public.kolis_org_outstanding_cents(p_org);
  if v_out + greatest(p_add_cents,0) > v_lim then raise exception 'credit_limit_exceeded'; end if;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_city_province(p_city text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case public.kolis_region_code(p_city)
    -- Ontario
    when 'ottawa' then 'ON' when 'kingston' then 'ON' when 'toronto' then 'ON'
    when 'mississauga' then 'ON' when 'hamilton' then 'ON' when 'london' then 'ON'
    when 'kitchener' then 'ON' when 'waterloo' then 'ON' when 'cambridge' then 'ON'
    when 'guelph' then 'ON' when 'windsor' then 'ON' when 'barrie' then 'ON'
    when 'oshawa' then 'ON' when 'brampton' then 'ON' when 'markham' then 'ON'
    when 'vaughan' then 'ON' when 'scarborough' then 'ON' when 'etobicoke' then 'ON'
    when 'kanata' then 'ON' when 'nepean' then 'ON' when 'orleans' then 'ON'
    when 'gloucester' then 'ON' when 'cornwall' then 'ON' when 'brockville' then 'ON'
    when 'belleville' then 'ON' when 'peterborough' then 'ON' when 'niagara' then 'ON'
    when 'sudbury' then 'ON' when 'richmond' then 'ON' when 'ajax' then 'ON' when 'whitby' then 'ON'
    -- Quebec
    when 'gatineau' then 'QC' when 'montreal' then 'QC' when 'quebec' then 'QC'
    when 'sherbrooke' then 'QC' when 'laval' then 'QC' when 'longueuil' then 'QC'
    when 'levis' then 'QC' when 'terrebonne' then 'QC' when 'drummondville' then 'QC'
    when 'granby' then 'QC' when 'trois-rivieres' then 'QC' when 'saguenay' then 'QC'
    when 'brossard' then 'QC' when 'repentigny' then 'QC' when 'saint-jerome' then 'QC'
    -- Other provinces (majors)
    when 'vancouver' then 'BC' when 'victoria' then 'BC' when 'burnaby' then 'BC' when 'surrey' then 'BC'
    when 'calgary' then 'AB' when 'edmonton' then 'AB'
    when 'winnipeg' then 'MB' when 'regina' then 'SK' when 'saskatoon' then 'SK'
    when 'halifax' then 'NS' when 'moncton' then 'NB' when 'fredericton' then 'NB'
    when 'charlottetown' then 'PE'
    else 'ON' end;  -- unknown destination → default ON
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_claim_admin_invite()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_email text; v_role text; v_caps text[];
begin
  select email into v_email from public.kolis_profiles where id = auth.uid();
  if v_email is null then return null; end if;
  select role, capabilities into v_role, v_caps from public.kolis_admin_invites where lower(email) = lower(v_email);
  if v_role is null then return null; end if;
  insert into public.kolis_admin_roles(user_id, role, capabilities, invited_email)
  values (auth.uid(), v_role, coalesce(v_caps,'{}'), v_email)
  on conflict (user_id) do update set role = excluded.role, capabilities = excluded.capabilities;
  delete from public.kolis_admin_invites where lower(email) = lower(v_email);
  return v_role;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_claim_founding(p_role text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  update public.kolis_founding set count = count + 1
    where role = p_role and count < 100
    returning count into n;
  return n; -- null when the 100 cap is reached
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_claim_webhook_deliveries(p_limit integer DEFAULT 20)
 RETURNS TABLE(id uuid, url text, secret text, payload jsonb, attempts integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return query
  update public.kolis_webhook_deliveries d
     set status = 'sending', attempts = d.attempts + 1
   where d.id in (select dd.id from public.kolis_webhook_deliveries dd
                  where dd.status = 'pending' and dd.next_attempt_at <= now()
                  order by dd.next_attempt_at for update skip locked limit p_limit)
  returning d.id,
            (select w.url from public.kolis_webhook_endpoints w where w.id = d.endpoint_id),
            (select w.secret from public.kolis_webhook_endpoints w where w.id = d.endpoint_id),
            d.payload, d.attempts;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_close_billing_period(p_start date, p_end date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o record; inv uuid; n_created int := 0; v_sub bigint; v_disc bigint; v_tax bigint; v_rate numeric;
begin
  perform pg_advisory_xact_lock(hashtext('kolis_billing_close'));
  for o in select * from public.kolis_orgs loop
    -- skip orgs with nothing new to bill in the window
    if not exists (
      select 1 from public.kolis_parcels p
      where p.org_id = o.id and p.billing_mode='invoice' and p.status='delivered'
        and p.billed_invoice_id is null
        and p.delivered_at >= p_start and p.delivered_at < (p_end + 1)) then
      continue;
    end if;

    -- get-or-create the draft invoice for this exact period (idempotent)
    insert into public.kolis_invoices(org_id, period_start, period_end, status)
    values (o.id, p_start, p_end, 'draft')
    on conflict (org_id, period_start, period_end) do nothing
    returning id into inv;
    if inv is null then
      select id into inv from public.kolis_invoices
        where org_id=o.id and period_start=p_start and period_end=p_end;
      -- only accrue onto an invoice still in draft (never re-bill an issued one)
      if (select status from public.kolis_invoices where id=inv) <> 'draft' then continue; end if;
    else
      n_created := n_created + 1;
    end if;

    -- one line per unbilled delivered parcel (unique parcel_id makes this safe)
    insert into public.kolis_invoice_lines(invoice_id, parcel_id, description, amount_cents)
    select inv, p.id, 'Parcel '||p.code||' · '||p.from_city||' → '||p.to_city,
           p.price_cents + coalesce(p.insurance_premium_cents,0)
    from public.kolis_parcels p
    where p.org_id=o.id and p.billing_mode='invoice' and p.status='delivered'
      and p.billed_invoice_id is null
      and p.delivered_at >= p_start and p.delivered_at < (p_end + 1)
    on conflict (parcel_id) do nothing;

    -- claim those parcels in the same predicate (the double-bill guard)
    update public.kolis_parcels p
      set billed_invoice_id = inv, accrued_at = now()
    where p.org_id=o.id and p.billing_mode='invoice' and p.status='delivered'
      and p.billed_invoice_id is null
      and p.delivered_at >= p_start and p.delivered_at < (p_end + 1);

    -- recompute totals from the authoritative lines
    select coalesce(sum(amount_cents),0) into v_sub from public.kolis_invoice_lines where invoice_id=inv;
    v_disc := round(v_sub * o.discount_rate);
    v_rate := public.kolis_tax_rate(o.country, o.province);
    v_tax  := round((v_sub - v_disc) * v_rate);
    update public.kolis_invoices
      set subtotal_cents=v_sub, discount_cents=v_disc, tax_cents=v_tax,
          total_cents=(v_sub - v_disc + v_tax),
          due_at = ((p_end + 1)::timestamptz + (o.net_terms_days || ' days')::interval)
      where id=inv;
  end loop;
  return n_created;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_close_carrier_payouts(p_start date, p_end date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o record; stmt uuid; n int := 0; v_gross bigint; v_fee bigint;
begin
  perform pg_advisory_xact_lock(hashtext('kolis_carrier_payout_close'));
  for o in select * from public.kolis_orgs where type in ('carrier','both') loop
    if not exists (select 1 from public.kolis_parcels p
                   where p.carrier_org_id=o.id and p.status='delivered'
                     and p.driver_paid_at is null and p.paid_statement_id is null
                     and p.delivered_at >= p_start and p.delivered_at < (p_end+1)) then
      continue;
    end if;
    insert into public.kolis_payout_statements(org_id, period_start, period_end, status)
    values (o.id, p_start, p_end, 'pending')
    on conflict (org_id, period_start, period_end) do nothing returning id into stmt;
    if stmt is null then
      select id into stmt from public.kolis_payout_statements where org_id=o.id and period_start=p_start and period_end=p_end;
      if (select status from public.kolis_payout_statements where id=stmt) <> 'pending' then continue; end if;
    else n := n + 1; end if;

    update public.kolis_parcels p set paid_statement_id = stmt
     where p.carrier_org_id=o.id and p.status='delivered'
       and p.driver_paid_at is null and p.paid_statement_id is null
       and p.delivered_at >= p_start and p.delivered_at < (p_end+1);

    delete from public.kolis_payout_statement_lines where statement_id=stmt;
    insert into public.kolis_payout_statement_lines(statement_id, driver_id, parcels, gross_cents)
    select stmt, p.driver_id, count(*)::int, sum(p.driver_payout_cents)::bigint
    from public.kolis_parcels p where p.paid_statement_id=stmt group by p.driver_id;

    select coalesce(sum(driver_payout_cents),0) into v_gross from public.kolis_parcels where paid_statement_id=stmt;
    v_fee := round(v_gross * o.platform_fee_rate);
    update public.kolis_payout_statements set gross_cents=v_gross, platform_fee_cents=v_fee, net_cents=(v_gross - v_fee) where id=stmt;
  end loop;
  return n;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_complete_webhook_delivery(p_id uuid, p_ok boolean, p_code integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_ok then
    update public.kolis_webhook_deliveries set status='delivered', response_code=p_code where id=p_id;
  else
    update public.kolis_webhook_deliveries
       set status = case when attempts >= 6 then 'failed' else 'pending' end,
           response_code = p_code,
           next_attempt_at = now() + (power(2, least(attempts,6)) || ' minutes')::interval
     where id = p_id;
  end if;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_courier_pickup(p_id uuid, p_code text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_kp uuid; v_code text; cnt int;
begin
  select coalesce((select kp.id from public.kolis_profiles kp
                   where kp.id = auth.uid() or kp.loadq_driver_id = auth.uid()
                   order by (kp.id = auth.uid()) desc limit 1), auth.uid()) into v_kp;
  select pickup_code into v_code from public.kolis_parcels
    where id = p_id and driver_id = v_kp and status = 'matched';
  if v_code is null then return 'fail'; end if;
  if btrim(p_code) <> v_code then return 'bad_code'; end if;
  update public.kolis_parcels set status = 'picked_up'
    where id = p_id and driver_id = v_kp and status = 'matched';
  get diagnostics cnt = row_count;
  return case when cnt > 0 then 'ok' else 'fail' end;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_decline_parcel(p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.kolis_parcels
     set preferred_driver_id = null, offer_expires_at = null
   where id = p_id and preferred_driver_id = auth.uid() and driver_id is null;
  return found;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_deny_claim(p_id uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.kolis_admin_has_cap('claims') then raise exception 'forbidden'; end if;
  update public.kolis_claims set status='denied', note=coalesce(p_note,note), resolved_by=auth.uid(), resolved_at=now()
   where id=p_id and status='open';
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_dest_tax_rate(p_city text, p_country text DEFAULT 'CA'::text)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select public.kolis_tax_rate(coalesce(p_country,'CA'), public.kolis_city_province(p_city));
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_distance_m(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision)
 RETURNS double precision
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when lat1 is null or lng1 is null or lat2 is null or lng2 is null then null else
    6371000 * 2 * asin(sqrt(
      power(sin(radians(lat2-lat1)/2),2) +
      cos(radians(lat1))*cos(radians(lat2))*power(sin(radians(lng2-lng1)/2),2)
    )) end;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_driver_payout_cents(p_price_cents integer, p_drop text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select (round(p_price_cents * case when p_drop = 'door' then 0.45 else (2.0/3.0) end))::int;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_enforce_suspensions()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  update public.kolis_orgs o set status = 'suspended'
  where o.status = 'active'
    and (public.kolis_org_outstanding_cents(o.id) > o.credit_limit_cents
         or exists (select 1 from public.kolis_invoices i
                    where i.org_id = o.id and i.status = 'open' and i.due_at < now()));
  get diagnostics n = row_count;
  return n;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_enqueue_webhooks()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ev text; e record; payload jsonb;
begin
  if tg_op = 'INSERT' then
    ev := case when new.org_id is not null then 'shipment.created' else null end;
  elsif new.status is distinct from old.status then
    ev := case new.status
      when 'matched' then 'shipment.matched' when 'picked_up' then 'shipment.picked_up'
      when 'in_transit' then 'shipment.in_transit' when 'delivered' then 'shipment.delivered'
      when 'cancelled' then 'shipment.cancelled' else null end;
  end if;
  if ev is null then return new; end if;
  payload := jsonb_build_object('event',ev,'parcel_id',new.id,'code',new.code,'status',new.status,
    'from_city',new.from_city,'to_city',new.to_city,'org_id',new.org_id,'carrier_org_id',new.carrier_org_id,
    'at', now());
  for e in select * from public.kolis_webhook_endpoints w
           where w.active and (w.org_id = new.org_id or w.org_id = new.carrier_org_id)
             and (cardinality(w.events) = 0 or ev = any(w.events)) loop
    insert into public.kolis_webhook_deliveries(endpoint_id, parcel_id, event, payload, idempotency_key)
    values (e.id, new.id, ev, payload, e.id || ':' || new.id || ':' || ev)
    on conflict (idempotency_key) do nothing;
  end loop;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_estimate_price_cents(p_size text, p_drop text, p_from text, p_to text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare km int; base numeric; mult numeric;
begin
  km := public.kolis_route_km(p_from, p_to);
  base := case when p_drop = 'door' then 5 + 0.20*km else 10 + 0.10*km end;
  mult := case p_size when 'envelope' then 0.75 when 'large' then 1.6 else 1.0 end;
  return (round(base * mult))::int * 100;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_freight_list(p_status text DEFAULT NULL::text)
 RETURNS SETOF kolis_freight_requests
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from public.kolis_freight_requests
  where public.kolis_is_staff() and (p_status is null or status = p_status)
  order by created_at desc limit 500;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_freight_set_booked(p_id uuid, p_tracking text, p_carrier text, p_url text)
 RETURNS kolis_freight_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.kolis_freight_requests;
begin
  if not public.kolis_is_staff() then raise exception 'forbidden'; end if;
  update public.kolis_freight_requests
    set status='booked', tracking_number=nullif(p_tracking,''), carrier=nullif(p_carrier,''),
        tracking_url=nullif(p_url,''), booked_at=now()
    where id=p_id returning * into v;
  return v;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_freight_set_quote(p_id uuid, p_price numeric, p_service text)
 RETURNS kolis_freight_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.kolis_freight_requests;
begin
  if not public.kolis_is_staff() then raise exception 'forbidden'; end if;
  update public.kolis_freight_requests
    set quoted_price=p_price, quoted_service=p_service, quoted_at=now(), status='quoted'
    where id=p_id returning * into v;
  return v;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_freight_set_status(p_id uuid, p_status text)
 RETURNS kolis_freight_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.kolis_freight_requests;
begin
  if not public.kolis_is_staff() then raise exception 'forbidden'; end if;
  if p_status not in ('new','quoted','booked','lost') then raise exception 'bad status'; end if;
  update public.kolis_freight_requests set status=p_status where id=p_id returning * into v;
  return v;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_freight_track(p_tracking text)
 RETURNS TABLE(origin text, destination text, pallets integer, status text, carrier text, tracking_url text, booked_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select origin, destination, pallets, status, carrier, tracking_url, booked_at
  from public.kolis_freight_requests
  where tracking_number is not null and lower(tracking_number)=lower(trim(p_tracking))
  limit 1;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_gen_parcel_code()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare c text;
begin
  loop
    c := 'KL-' || lpad((floor(random()*9000)+1000)::int::text, 4, '0');
    exit when not exists (select 1 from public.kolis_parcels where code = c);
  end loop;
  return c;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_geocode_heal()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'net'
AS $function$
declare r record; n int := 0;
begin
  for r in
    select id from public.kolis_parcels
    where (dropoff_lat is null or pickup_lat is null)
      and coalesce(nullif(btrim(dropoff_addr),''), nullif(btrim(to_city),''), nullif(btrim(from_city),'')) is not null
      and status <> 'cancelled'
      and created_at > now() - interval '45 days'
    order by created_at desc
    limit 25
  loop
    perform net.http_post(
      url := 'https://kzjptcpjpwlxfofzhyku.supabase.co/functions/v1/kolis-geocode',
      headers := jsonb_build_object('Content-Type','application/json','x-kolis-secret','kolis_geocode_2f7a'),
      body := jsonb_build_object('parcel_id', r.id));
    n := n + 1;
  end loop;
  return n;
end; $function$
;

