CREATE OR REPLACE FUNCTION public.kolis_mark_carrier_statement_paid(p_statement uuid, p_ref text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.kolis_payout_statements set status='paid', paid_at=now(), interac_ref=p_ref
   where id=p_statement and status='pending';
  if not found then return false; end if;
  update public.kolis_parcels set driver_paid_at=now() where paid_statement_id=p_statement and driver_paid_at is null;
  return true;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_mark_paid(p_driver uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if not exists (select 1 from public.drivers a where a.id = auth.uid() and a.is_admin) then return -1; end if;
  update public.kolis_parcels set driver_paid_at = now()
    where driver_id = p_driver and status = 'delivered' and driver_paid_at is null;
  get diagnostics n = row_count;
  return n;
end; $function$
;

