CREATE OR REPLACE FUNCTION public.kolis_my_shipments(p_org uuid DEFAULT NULL::uuid)
 RETURNS SETOF kolis_parcels
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_org is null then
    return query
      select * from public.kolis_parcels
      where sender_id = auth.uid() and org_id is null
      order by created_at desc;
  else
    if coalesce(public.kolis_org_role(p_org),'') = '' then
      raise exception 'forbidden';
    end if;
    return query
      select * from public.kolis_parcels
      where org_id = p_org
      order by created_at desc;
  end if;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_next_business_day(p_ts timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select ((p_ts::date + case extract(isodow from p_ts)::int
            when 6 then 2   -- Sat -> Mon
            when 7 then 1   -- Sun -> Mon
            else 0 end)::timestamptz + interval '13 hours');
$function$
;

