CREATE OR REPLACE FUNCTION public.kolis_notify_drain()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'net'
AS $function$
declare r record; v_code int; v_req bigint; conf int:=0; retried int:=0; dead int:=0;
        v_url text := 'https://kzjptcpjpwlxfofzhyku.supabase.co/functions/v1/kolis-notify-recipient';
        v_hdr jsonb := jsonb_build_object('Content-Type','application/json','x-kolis-secret','kolis_notify_9f3a2c7b1e6d4084');
begin
  -- 1) confirm inflight
  for r in select * from public.kolis_notifications where state='inflight' loop
    select status_code into v_code from net._http_response where id = r.request_id;
    if v_code is not null and v_code between 200 and 299 then
      update public.kolis_notifications set state='sent', sent_at=now(), last_error=null where id=r.id; conf:=conf+1;
    elsif v_code is not null then
      update public.kolis_notifications set state='pending', last_error='http '||v_code where id=r.id;
    elsif r.last_attempt_at < now() - interval '2 minutes' then
      update public.kolis_notifications set state='pending', last_error='no_response' where id=r.id;
    end if;
  end loop;
  -- 2) retry pending
  for r in select * from public.kolis_notifications where state='pending' and attempts < 6 order by created_at limit 40 loop
    select net.http_post(url:=v_url, headers:=v_hdr, body:=jsonb_build_object('parcel_id',r.parcel_id,'status',r.kind)) into v_req;
    update public.kolis_notifications set request_id=v_req, state='inflight', attempts=attempts+1, last_attempt_at=now() where id=r.id; retried:=retried+1;
  end loop;
  -- 3) give up
  update public.kolis_notifications set state='dead' where state='pending' and attempts>=6;
  get diagnostics dead = row_count;
  return jsonb_build_object('confirmed',conf,'retried',retried,'dead',dead);
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_notify_new_parcel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tok text;
begin
  if new.driver_id is null and new.status in ('requested','received_at_hub') then
    select decrypted_secret into tok from vault.decrypted_secrets where name='kolis_alert_key';
    perform net.http_post(
      url := 'https://kzjptcpjpwlxfofzhyku.supabase.co/functions/v1/kolis-new-parcel-alert',
      headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||tok),
      body := jsonb_build_object('parcel_id', new.id)
    );
  end if;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_notify_recipient_created_trg()
 RETURNS trigger
