CREATE OR REPLACE FUNCTION public.kolis_org_account_get(p_org uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'name', o.name, 'phone', o.phone, 'billing_email', o.billing_email,
    'address', o.address, 'city', o.city, 'postal', o.postal, 'country', coalesce(o.country,'CA'),
    'role', public.kolis_org_role(p_org),
    'complete', (coalesce(nullif(btrim(o.phone),''),'')<>'' and coalesce(nullif(btrim(o.billing_email),''),'')<>'' and coalesce(nullif(btrim(o.address),''),'')<>'')
  )
  from public.kolis_orgs o where o.id=p_org and coalesce(public.kolis_org_role(p_org),'')<>'';
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_account_save(p_org uuid, p_phone text, p_email text, p_address text, p_city text, p_postal text, p_country text DEFAULT 'CA'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin') then raise exception 'forbidden'; end if;
  if coalesce(nullif(btrim(p_phone),''),'')   = '' then raise exception 'phone_required'; end if;
  if coalesce(nullif(btrim(p_email),''),'')   = '' then raise exception 'email_required'; end if;
  if coalesce(nullif(btrim(p_address),''),'') = '' then raise exception 'address_required'; end if;
  update public.kolis_orgs set phone=btrim(p_phone), billing_email=btrim(p_email), address=btrim(p_address),
    city=nullif(btrim(p_city),''), postal=nullif(btrim(p_postal),''), country=coalesce(nullif(btrim(p_country),''),'CA') where id=p_org;
  return public.kolis_org_account_get(p_org);
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_add_credit(p_org uuid, p_cents bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v bigint;
begin
  update public.kolis_orgs set credit_cents = coalesce(credit_cents,0) + greatest(p_cents,0)
   where id = p_org returning credit_cents into v;
  return coalesce(v,0);
