 RETURNS TABLE(id uuid, name text, item_count integer, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  return query
    select d.id, d.name, coalesce(jsonb_array_length(d.rows),0)::int, d.created_at, d.updated_at
    from public.kolis_bulk_drafts d
    where d.org_id = p_org
    order by d.updated_at desc;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_bulk_quote(p_org uuid, p_pickup jsonb, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r jsonb; res jsonb := '[]'::jsonb; i int := 0; v_price int; v_tax int; v_rate numeric; v_dtype text; v_from text; v_hub uuid;
        subtotal int := 0; tax_total int := 0; rate_seen numeric := null; mixed boolean := false;
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  v_dtype := coalesce(p_pickup->>'dropoff_type','door');
  v_hub := nullif(p_pickup->>'hub_id','')::uuid;
  v_from := coalesce(nullif(p_pickup->>'from_city',''),'Ottawa');
  if v_dtype='hub' and v_hub is not null then select coalesce(nullif(city,''),v_from) into v_from from public.kolis_hubs where id=v_hub; end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    i := i+1;
    v_price := coalesce(public.kolis_org_price_cents(p_org, coalesce(r->>'size','small'), v_dtype, v_from, coalesce(r->>'to_city','')), 0);
    v_rate := public.kolis_dest_tax_rate(coalesce(r->>'to_city',''));
    v_tax := round(v_price * v_rate);
    if rate_seen is null then rate_seen := v_rate; elsif rate_seen <> v_rate then mixed := true; end if;
    subtotal := subtotal + v_price; tax_total := tax_total + v_tax;
    res := res || jsonb_build_object('index',i,'price_cents',v_price,'tax_cents',v_tax,'tax_rate',v_rate);
  end loop;
  return jsonb_build_object('rows',res,'total_cents',subtotal,'subtotal_cents',subtotal,
                            'tax_cents',tax_total,'tax_rate', case when mixed then null else rate_seen end,
                            'grand_total_cents',subtotal+tax_total);
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_bulk_ship(p_org uuid, p_pickup jsonb, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r jsonb; res jsonb := '[]'::jsonb; i int := 0; v_id uuid; v_code text; v_price int;
        v_dtype text; v_size text; v_from text; v_hub uuid; v_pickaddr text; v_status text; v_payg boolean; v_billing text;
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin','shipper') then raise exception 'forbidden'; end if;
  if (select status from public.kolis_orgs where id = p_org) <> 'active' then raise exception 'org_inactive'; end if;
  select coalesce(payg,false) into v_payg from public.kolis_orgs where id = p_org;
  v_billing := case when v_payg then 'card' else 'invoice' end;

  v_dtype := coalesce(p_pickup->>'dropoff_type','door');
  if v_dtype not in ('door','zone','hub') then raise exception 'bad_dropoff'; end if;
  v_hub := nullif(p_pickup->>'hub_id','')::uuid;
  v_pickaddr := nullif(p_pickup->>'pickup_addr','');
  v_from := coalesce(nullif(p_pickup->>'from_city',''), 'Ottawa');
  if v_dtype = 'hub' and v_hub is not null then
    select coalesce(nullif(city,''), v_from) into v_from from public.kolis_hubs where id = v_hub;
  end if;

  for r in select * from jsonb_array_elements(p_rows) loop
    i := i + 1;
    begin
      v_size := coalesce(r->>'size','small');
      if v_size not in ('envelope','small','large') then raise exception 'bad_size'; end if;
      if coalesce(r->>'to_city','') = '' then raise exception 'missing to_city'; end if;
      v_price := public.kolis_org_price_cents(p_org, v_size, v_dtype, v_from, r->>'to_city');
      if not v_payg then perform public.kolis_check_credit(p_org, v_price); end if;
      v_status := case when v_dtype='hub' then 'received_at_hub' else 'requested' end;
      insert into public.kolis_parcels(
        code, sender_id, status, dropoff_type, size, from_city, to_city, to_region,
        price_cents, driver_payout_cents, billing_mode, org_id, client_id,
        pickup_hub, pickup_addr,
        recipient_name, recipient_phone, recipient_email, recipient_lang, dropoff_addr,
        contents_description, insurance_premium_cents)
      values (
        public.kolis_gen_parcel_code(), auth.uid(), v_status, v_dtype, v_size, v_from, r->>'to_city', public.kolis_region_code(r->>'to_city'),
        v_price, public.kolis_driver_payout_cents(v_price, v_dtype), v_billing, p_org, nullif(r->>'client_id','')::uuid,
        case when v_dtype='hub' then v_hub else null end,
        case when v_dtype<>'hub' then v_pickaddr else null end,
        nullif(r->>'to_name',''), nullif(r->>'to_phone',''), nullif(r->>'to_email',''),
        case when lower(coalesce(r->>'lang','')) in ('en','fr') then lower(r->>'lang') else null end,
        nullif(r->>'to_address',''),
        nullif(r->>'contents',''), 0)
      returning id, code into v_id, v_code;
      res := res || jsonb_build_object('index',i,'ok',true,'id',v_id,'code',v_code,'price_cents',v_price,'to_name',r->>'to_name');
    exception when others then
      res := res || jsonb_build_object('index',i,'ok',false,'error',sqlerrm,'to_name',r->>'to_name');
    end;
  end loop;
  return jsonb_build_object('results', res, 'payg', v_payg);
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_client_delete(p_org uuid, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin','shipper') then raise exception 'forbidden'; end if;
  delete from public.kolis_org_clients where id=p_id and org_id=p_org;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_client_get(p_org uuid, p_id uuid)
 RETURNS kolis_org_clients
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from public.kolis_org_clients c
  where c.id = p_id and c.org_id = p_org and coalesce(public.kolis_org_role(p_org),'') <> '';
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_client_history(p_org uuid, p_client_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(x order by (x->>'created_at') desc), '[]'::jsonb) from (
    select jsonb_build_object(
      'id', p.id, 'code', p.code, 'created_at', p.created_at, 'status', p.status,
      'from_city', p.from_city, 'to_city', p.to_city, 'dropoff_type', p.dropoff_type,
      'size', p.size, 'price_cents', p.price_cents, 'dropoff_addr', p.dropoff_addr,
      'contents', p.contents_description,
      'tax_cents', coalesce(p.tax_cents, round(p.price_cents * public.kolis_dest_tax_rate(p.to_city))::int)
    ) as x
    from public.kolis_parcels p
    where p.org_id = p_org and p.client_id = p_client_id
      and coalesce(public.kolis_org_role(p_org),'') <> ''
  ) t;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_client_save(p_org uuid, p_id uuid, p_full_name text, p_email text, p_mobile text, p_home text, p_work text, p_address text, p_city text, p_province text, p_postal text, p_notes text, p_country text DEFAULT 'CA'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin','shipper') then raise exception 'forbidden'; end if;
  if coalesce(nullif(btrim(p_full_name),''),'') = '' then raise exception 'name_required'; end if;
  if coalesce(nullif(btrim(p_email),''),'')   = '' then raise exception 'email_required'; end if;
  if coalesce(nullif(btrim(p_mobile),''),'')  = '' then raise exception 'phone_required'; end if;
  if coalesce(nullif(btrim(p_address),''),'') = '' then raise exception 'address_required'; end if;
  if p_id is null then
    insert into public.kolis_org_clients(org_id, full_name, email, mobile, home_phone, work_phone, address, city, province, postal, country, notes)
    values (p_org, btrim(p_full_name), nullif(btrim(p_email),''), nullif(btrim(p_mobile),''), nullif(btrim(p_home),''), nullif(btrim(p_work),''),
            nullif(btrim(p_address),''), nullif(btrim(p_city),''), nullif(btrim(p_province),''), nullif(btrim(p_postal),''), coalesce(nullif(btrim(p_country),''),'CA'), nullif(btrim(p_notes),''))
    returning id into v_id;
  else
    update public.kolis_org_clients set
      full_name=btrim(p_full_name), email=nullif(btrim(p_email),''), mobile=nullif(btrim(p_mobile),''),
      home_phone=nullif(btrim(p_home),''), work_phone=nullif(btrim(p_work),''), address=nullif(btrim(p_address),''),
      city=nullif(btrim(p_city),''), province=nullif(btrim(p_province),''), postal=nullif(btrim(p_postal),''),
      country=coalesce(nullif(btrim(p_country),''),'CA'), notes=nullif(btrim(p_notes),''), updated_at=now()
    where id=p_id and org_id=p_org returning id into v_id;
    if v_id is null then raise exception 'not_found'; end if;
  end if;
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_clients_list(p_org uuid, p_search text DEFAULT NULL::text)
 RETURNS SETOF kolis_org_clients
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from public.kolis_org_clients c
  where c.org_id = p_org and coalesce(public.kolis_org_role(p_org),'') <> ''
    and (p_search is null or p_search = ''
      or c.full_name ilike '%'||p_search||'%' or c.email ilike '%'||p_search||'%'
      or c.mobile ilike '%'||p_search||'%' or c.city ilike '%'||p_search||'%')
  order by c.full_name;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_consume_credit(p_org uuid, p_want_cents bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_bal bigint; v_use bigint;
begin
  select coalesce(credit_cents,0) into v_bal from public.kolis_orgs where id = p_org for update;
  if v_bal is null then return 0; end if;
  v_use := least(v_bal, greatest(p_want_cents,0));
  if v_use > 0 then update public.kolis_orgs set credit_cents = v_bal - v_use where id = p_org; end if;
  return v_use;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_create_key(p_org uuid, p_name text, p_scopes text[])
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_plain text; v_prefix text;
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin') then raise exception 'forbidden'; end if;
  v_plain  := 'kolis_live_' || encode(extensions.gen_random_bytes(24), 'hex');
  v_prefix := substr(v_plain, 1, 16);
  insert into public.kolis_access_keys(name, prefix, key_hash, scopes, created_by, org_id)
  values (p_name, v_prefix, encode(extensions.digest(v_plain, 'sha256'), 'hex'), coalesce(p_scopes, '{}'), auth.uid(), p_org);
  return v_plain;   -- shown once; only the hash is stored
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_create_shipment(p_org uuid, p_dropoff_type text, p_size text, p_from_city text, p_to_city text, p_recipient_name text DEFAULT NULL::text, p_recipient_phone text DEFAULT NULL::text, p_recipient_email text DEFAULT NULL::text, p_dropoff_addr text DEFAULT NULL::text, p_pickup_addr text DEFAULT NULL::text, p_contents text DEFAULT NULL::text, p_declared_value_cents integer DEFAULT NULL::integer, p_insured boolean DEFAULT false, p_client_ref text DEFAULT NULL::text, p_recipient_lang text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_code text; v_price int; v_status text; v_ins int;
        v_payg boolean; v_has_card boolean; v_billing text;
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin','shipper') then raise exception 'forbidden'; end if;
  if (select status from public.kolis_orgs where id = p_org) <> 'active' then raise exception 'org_inactive'; end if;
  if p_dropoff_type not in ('door','zone','hub') then raise exception 'bad_dropoff'; end if;
  if p_size not in ('envelope','small','large') then raise exception 'bad_size'; end if;

  select coalesce(payg,false), (stripe_default_pm is not null)
    into v_payg, v_has_card from public.kolis_orgs where id = p_org;
  v_billing := case when v_payg then 'card' else 'invoice' end;

  if p_client_ref is not null then
    select id, code into v_id, v_code from public.kolis_parcels where org_id = p_org and client_ref = p_client_ref;
    if v_id is not null then return jsonb_build_object('id',v_id,'code',v_code,'dedup',true,'payg',v_payg,'has_card',v_has_card); end if;
  end if;

  v_price := public.kolis_org_price_cents(p_org, p_size, p_dropoff_type, p_from_city, p_to_city);
  v_ins   := case when p_insured and p_declared_value_cents is not null then round(p_declared_value_cents * 0.05)::int else 0 end;
  -- Pay-as-you-go is charged per shipment (kolis-org-charge), so it never draws on invoice credit.
  if not v_payg then
    perform public.kolis_check_credit(p_org, v_price + v_ins);   -- race-safe credit guard
  end if;
  v_status := case when p_dropoff_type = 'hub' then 'received_at_hub' else 'requested' end;

  insert into public.kolis_parcels(
    code, sender_id, status, dropoff_type, size, from_city, to_city, to_region,
    price_cents, driver_payout_cents, billing_mode, org_id, client_ref,
    recipient_name, recipient_phone, recipient_email, recipient_lang, dropoff_addr, pickup_addr,
    contents_description, declared_value_cents, insured, insurance_premium_cents)
  values (
    public.kolis_gen_parcel_code(), auth.uid(), v_status, p_dropoff_type, p_size, p_from_city, p_to_city,
    public.kolis_region_code(p_to_city),
    v_price, public.kolis_driver_payout_cents(v_price, p_dropoff_type), v_billing, p_org, p_client_ref,
    p_recipient_name, p_recipient_phone, p_recipient_email, case when lower(btrim(coalesce(p_recipient_lang,''))) in ('en','fr') then lower(btrim(p_recipient_lang)) else null end, p_dropoff_addr, p_pickup_addr,
    p_contents, p_declared_value_cents, coalesce(p_insured,false), v_ins)
  returning id, code into v_id, v_code;
  return jsonb_build_object('id', v_id, 'code', v_code, 'payg', v_payg, 'has_card', v_has_card);
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_create_webhook(p_org uuid, p_url text, p_events text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin') then raise exception 'forbidden'; end if;
  insert into public.kolis_webhook_endpoints(org_id, url, secret, events)
  values (p_org, p_url, encode(extensions.gen_random_bytes(24),'hex'), coalesce(p_events,'{}')) returning id into v_id;
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_delete_webhook(p_org uuid, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin') then raise exception 'forbidden'; end if;
  delete from public.kolis_webhook_endpoints where id = p_id and org_id = p_org;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_hubs(p_org uuid)
 RETURNS TABLE(id uuid, name text, city text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select id, name, city from public.kolis_hubs
  where coalesce(public.kolis_org_role(p_org),'') <> '' and coalesce(name,'') not ilike 'TEST%' order by city, name;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_invite_member(p_org uuid, p_email text, p_role text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin') then raise exception 'forbidden'; end if;
  if p_role not in ('owner','admin','finance','shipper','dispatcher','driver') then raise exception 'bad_role'; end if;
  insert into public.kolis_org_invites(org_id,email,role,invited_by)
  values (p_org, lower(trim(p_email)), p_role, auth.uid())
  on conflict (org_id, lower(email)) do update set role = excluded.role, accepted_at = null, invited_by = auth.uid()
  returning id into v_id;
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_invoice(p_org uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  select jsonb_build_object(
    'invoice', to_jsonb(i),
    'lines', coalesce((select jsonb_agg(to_jsonb(l) order by l.description) from public.kolis_invoice_lines l where l.invoice_id=i.id),'[]'::jsonb),
    'org', jsonb_build_object('name',o.name,'discount_rate',o.discount_rate,'province',o.province,'country',o.country))
  into v from public.kolis_invoices i join public.kolis_orgs o on o.id=i.org_id
  where i.id=p_id and i.org_id=p_org;
  if v is null then raise exception 'not_found'; end if;
  return v;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_invoices(p_org uuid)
 RETURNS SETOF kolis_invoices
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  return query select * from public.kolis_invoices where org_id = p_org order by period_start desc;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_keys(p_org uuid)
 RETURNS TABLE(id uuid, name text, prefix text, scopes text[], created_at timestamp with time zone, last_used_at timestamp with time zone, revoked_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  return query select k.id,k.name,k.prefix,k.scopes,k.created_at,k.last_used_at,k.revoked_at
    from public.kolis_access_keys k where k.org_id = p_org order by k.created_at desc;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_label(p_org uuid, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin','shipper') then raise exception 'forbidden'; end if;
  select jsonb_build_object(
    'id', p.id, 'code', p.code, 'from_city', p.from_city, 'to_city', p.to_city, 'dropoff_type', p.dropoff_type,
    'recipient_name', p.recipient_name, 'recipient_phone', p.recipient_phone, 'dropoff_addr', p.dropoff_addr,
    'pickup_code', p.pickup_code, 'delivery_code', p.delivery_code, 'scan_token', p.scan_token,
    'sender_name', coalesce(o.name,'Kolis')
  ) into v from public.kolis_parcels p left join public.kolis_orgs o on o.id = p.org_id
    where p.code = p_code and p.org_id = p_org;
  if v is null then raise exception 'not_found'; end if;
  return v;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_outstanding_cents(p_org uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    coalesce((select sum(total_cents) from public.kolis_invoices
              where org_id = p_org and status in ('draft','open','uncollectible')),0)
  + coalesce((select sum(price_cents + coalesce(insurance_premium_cents,0)) from public.kolis_parcels
              where org_id = p_org and billing_mode = 'invoice' and billed_invoice_id is null
                and status <> 'cancelled'),0);
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_overview(p_org uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_out bigint; v_lim bigint; v_status text; v_payg boolean; v_card boolean;
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  select credit_limit_cents, status, coalesce(payg,false), (stripe_default_pm is not null)
    into v_lim, v_status, v_payg, v_card from public.kolis_orgs where id = p_org;
  v_out := public.kolis_org_outstanding_cents(p_org);
  return (select jsonb_build_object(
    'in_transit',   count(*) filter (where status in ('matched','dispatched','picked_up','in_transit')),
    'awaiting',     count(*) filter (where status in ('requested','received_at_hub') and driver_id is null),
    'delivered_30d',count(*) filter (where status='delivered' and delivered_at > now() - interval '30 days'),
    'total',        count(*),
    'accrued_cents',coalesce(sum(price_cents + coalesce(insurance_premium_cents,0))
                      filter (where status='delivered' and billing_mode='invoice' and billed_invoice_id is null),0),
    'outstanding_cents', v_out,
    'credit_limit_cents', v_lim,
    'available_cents', greatest(v_lim - v_out, 0),
    'org_status', v_status,
    'payg', v_payg,
    'has_card', v_card
  ) from public.kolis_parcels where org_id = p_org);
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_payout_statements(p_org uuid)
 RETURNS SETOF kolis_payout_statements
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  return query select * from public.kolis_payout_statements where org_id=p_org order by period_start desc;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_plan(p_org uuid)
 RETURNS TABLE(plan text, plan_status text, fee_rate numeric, renews_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(o.plan,'free'), o.plan_status, coalesce(o.platform_fee_rate,0.20), o.plan_renews_at
  from public.kolis_orgs o
  where o.id = p_org
    and exists (select 1 from public.kolis_org_members m where m.org_id=o.id and m.user_id=auth.uid());
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_price_cents(p_org uuid, p_size text, p_dropoff_type text, p_from_city text, p_to_city text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v int;
begin
  select price_cents into v from public.kolis_org_price_overrides
    where org_id = p_org and dropoff_type = p_dropoff_type
      and to_city_norm = public.kolis_norm_city(p_to_city);
  if v is not null then return v; end if;
  return public.kolis_estimate_price_cents(p_size, p_dropoff_type, p_from_city, p_to_city);
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_remove_member(p_org uuid, p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') <> 'owner' then raise exception 'forbidden'; end if;
  if (select role from public.kolis_org_members where org_id=p_org and user_id=p_user) = 'owner'
     and (select count(*) from public.kolis_org_members where org_id=p_org and role='owner') <= 1 then
    raise exception 'cannot_remove_last_owner';
  end if;
  delete from public.kolis_org_members where org_id = p_org and user_id = p_user;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_revoke_key(p_org uuid, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin') then raise exception 'forbidden'; end if;
  update public.kolis_access_keys set revoked_at = now() where id = p_id and org_id = p_org and revoked_at is null;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_role(p_org uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select role from public.kolis_org_members where org_id = p_org and user_id = auth.uid();
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_save_address(p_org uuid, p_label text, p_name text, p_line1 text, p_city text, p_province text, p_postal text, p_phone text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin','shipper') then raise exception 'forbidden'; end if;
  insert into public.kolis_org_addresses(org_id,label,name,line1,city,province,postal,phone)
  values (p_org,p_label,p_name,p_line1,p_city,p_province,p_postal,p_phone) returning id into v_id;
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_set_branding(p_org uuid, p_logo_url text, p_color text, p_name text, p_tracking boolean, p_emails boolean, p_powered_by boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org), '') not in ('owner','admin') then raise exception 'forbidden'; end if;
  if p_color is not null and p_color !~ '^#[0-9A-Fa-f]{6}$' then raise exception 'bad_color'; end if;
  update public.kolis_orgs set
    brand_logo_url = p_logo_url, brand_color = p_color, brand_name = nullif(trim(coalesce(p_name, '')), ''),
    brand_tracking = coalesce(p_tracking, true), brand_emails = coalesce(p_emails, true), brand_powered_by = coalesce(p_powered_by, true)
  where id = p_org;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_set_role(p_org uuid, p_user uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin') then raise exception 'forbidden'; end if;
  if p_role not in ('owner','admin','finance','shipper','dispatcher','driver') then raise exception 'bad_role'; end if;
  -- never strip the last owner
  if p_role <> 'owner' and (select role from public.kolis_org_members where org_id=p_org and user_id=p_user) = 'owner'
     and (select count(*) from public.kolis_org_members where org_id=p_org and role='owner') <= 1 then
    raise exception 'cannot_demote_last_owner';
  end if;
  update public.kolis_org_members set role = p_role where org_id = p_org and user_id = p_user;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_shipments(p_org uuid, p_filter text DEFAULT 'all'::text, p_search text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, code text, status text, dropoff_type text, size text, from_city text, to_city text, recipient_name text, recipient_phone text, recipient_email text, dropoff_addr text, pickup_addr text, driver_id uuid, price_cents integer, billing_mode text, created_at timestamp with time zone, client_id uuid, contents text, tax_cents integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  return query
    select p.id,p.code,p.status,p.dropoff_type,p.size,p.from_city,p.to_city,
           p.recipient_name,p.recipient_phone,p.recipient_email,p.dropoff_addr,p.pickup_addr,
           p.driver_id,p.price_cents,p.billing_mode,p.created_at,p.client_id,p.contents_description,
           coalesce(p.tax_cents, round(p.price_cents * public.kolis_dest_tax_rate(p.to_city))::int)
    from public.kolis_parcels p
    where p.org_id = p_org
      and (p_filter = 'all'
        or (p_filter = 'active'    and p.status not in ('delivered','cancelled'))
        or (p_filter = 'delivered' and p.status = 'delivered'))
      and (p_search is null or p_search = ''
        or p.code ilike '%'||p_search||'%' or p.to_city ilike '%'||p_search||'%'
        or p.recipient_name ilike '%'||p_search||'%')
    order by p.created_at desc;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_tax(p_org uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_country text; v_prov text; v_rate numeric;
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  select coalesce(country,'CA'), province into v_country, v_prov from public.kolis_orgs where id = p_org;
  v_rate := public.kolis_tax_rate(v_country, v_prov);
  return jsonb_build_object(
    'rate', v_rate, 'province', v_prov, 'country', v_country,
    'label', case when v_country <> 'CA' then 'VAT'
                  when upper(coalesce(v_prov,'ON')) in ('ON','NB','NL','NS','PE') then 'HST'
                  when upper(coalesce(v_prov,'ON')) = 'QC' then 'GST+QST'
                  else 'GST' end);
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_team(p_org uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  return jsonb_build_object(
    'members', coalesce((select jsonb_agg(jsonb_build_object(
        'user_id',m.user_id,'role',m.role,'full_name',pr.full_name,'email',pr.email) order by m.created_at)
      from public.kolis_org_members m left join public.kolis_profiles pr on pr.id = m.user_id
      where m.org_id = p_org),'[]'::jsonb),
    'invites', coalesce((select jsonb_agg(jsonb_build_object('email',i.email,'role',i.role) order by i.created_at)
      from public.kolis_org_invites i where i.org_id = p_org and i.accepted_at is null),'[]'::jsonb));
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_update_shipment(p_org uuid, p_parcel uuid, p_dropoff_type text DEFAULT NULL::text, p_size text DEFAULT NULL::text, p_to_city text DEFAULT NULL::text, p_recipient_name text DEFAULT NULL::text, p_recipient_phone text DEFAULT NULL::text, p_recipient_email text DEFAULT NULL::text, p_dropoff_addr text DEFAULT NULL::text, p_pickup_addr text DEFAULT NULL::text, p_contents text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_p public.kolis_parcels%rowtype; v_dtype text; v_size text; v_city text; v_new int; v_old int;
begin
  if coalesce(public.kolis_org_role(p_org),'') not in ('owner','admin','shipper') then raise exception 'forbidden'; end if;
  select * into v_p from public.kolis_parcels where id = p_parcel and org_id = p_org;
  if not found then raise exception 'not_found'; end if;
  if v_p.driver_id is not null or v_p.status not in ('requested','received_at_hub') then raise exception 'shipment_locked'; end if;

  v_dtype := coalesce(nullif(btrim(p_dropoff_type),''), v_p.dropoff_type);
  v_size  := coalesce(nullif(btrim(p_size),''), v_p.size);
  v_city  := coalesce(nullif(btrim(p_to_city),''), v_p.to_city);
  if v_dtype not in ('door','zone','hub') then raise exception 'bad_dropoff'; end if;
  if v_size not in ('envelope','small','large') then raise exception 'bad_size'; end if;

  v_old := v_p.price_cents;
  v_new := public.kolis_org_price_cents(p_org, v_size, v_dtype, v_p.from_city, v_city);

  update public.kolis_parcels set
    dropoff_type = v_dtype, size = v_size, to_city = v_city,
    to_region = public.kolis_region_code(v_city),
    recipient_name  = coalesce(p_recipient_name,  recipient_name),
    recipient_phone = coalesce(p_recipient_phone, recipient_phone),
    recipient_email = coalesce(p_recipient_email, recipient_email),
    dropoff_addr    = coalesce(p_dropoff_addr,    dropoff_addr),
    pickup_addr     = coalesce(p_pickup_addr,     pickup_addr),
    contents_description = coalesce(p_contents, contents_description),
    price_cents = v_new,
    driver_payout_cents = public.kolis_driver_payout_cents(v_new, v_dtype)
  where id = p_parcel;

  return jsonb_build_object('id', v_p.id, 'code', v_p.code,
    'old_price_cents', v_old, 'new_price_cents', v_new, 'delta_cents', v_new - v_old,
    'billing_mode', v_p.billing_mode, 'stripe_payment_intent_id', v_p.stripe_payment_intent_id);
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_webhook_deliveries(p_org uuid)
 RETURNS TABLE(id uuid, event text, status text, attempts integer, response_code integer, url text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  return query select d.id, d.event, d.status, d.attempts, d.response_code, w.url, d.created_at
    from public.kolis_webhook_deliveries d join public.kolis_webhook_endpoints w on w.id = d.endpoint_id
    where w.org_id = p_org order by d.created_at desc limit 50;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_org_webhooks(p_org uuid)
 RETURNS TABLE(id uuid, url text, secret text, events text[], active boolean, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(public.kolis_org_role(p_org),'') = '' then raise exception 'forbidden'; end if;
  return query select w.id,w.url,w.secret,w.events,w.active,w.created_at
    from public.kolis_webhook_endpoints w where w.org_id = p_org order by w.created_at desc;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_parcel_receipt(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  me uuid := auth.uid();
  p public.kolis_parcels;
  base jsonb;
begin
  select * into p from public.kolis_parcels where id = p_id;
  if not found then return null; end if;
  if me is null or (me <> p.sender_id and me <> coalesce(p.driver_id, '00000000-0000-0000-0000-000000000000')) then
    return null;
  end if;
  base := jsonb_build_object(
    'id', p.id, 'code', p.code,
    'from_city', p.from_city, 'to_city', p.to_city,
    'size', p.size, 'dropoff_type', p.dropoff_type, 'status', p.status,
    'delivered_at', p.delivered_at, 'created_at', p.created_at,
    'role', case when me = p.sender_id then 'sender' else 'courier' end
  );
  if me = p.sender_id then
    return base || jsonb_build_object(
      'price_cents', p.price_cents,
      'insurance_premium_cents', coalesce(p.insurance_premium_cents, 0),
      'insured', p.insured);
  else
    return base || jsonb_build_object('payout_cents', p.driver_payout_cents);
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_parcels_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user in ('postgres','supabase_admin','supabase_auth_admin','service_role') then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.org_id is not null or new.carrier_org_id is not null
       or coalesce(new.billing_mode,'card') <> 'card' or new.billed_invoice_id is not null
       or new.paid_statement_id is not null or new.driver_paid_at is not null then
      raise exception 'kolis_parcels: org/billing fields are managed server-side';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.org_id            is distinct from old.org_id
       or new.carrier_org_id is distinct from old.carrier_org_id
       or new.billing_mode   is distinct from old.billing_mode
       or new.billed_invoice_id is distinct from old.billed_invoice_id
       or new.paid_statement_id is distinct from old.paid_statement_id
       or new.driver_paid_at  is distinct from old.driver_paid_at
       or new.accrued_at     is distinct from old.accrued_at
       or new.price_cents    is distinct from old.price_cents
       or new.driver_payout_cents is distinct from old.driver_payout_cents then
      raise exception 'kolis_parcels: org/billing fields are managed server-side';
    end if;
  end if;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_parcels_set_region()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.to_city is not null and btrim(new.to_city) <> '' then
    new.to_region := public.kolis_region_code(new.to_city);
  end if;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_pending_payouts()
 RETURNS TABLE(driver_id uuid, driver_name text, interac_email text, pending_cents bigint, parcels integer)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select p.driver_id, d.full_name, dp.interac_email, sum(p.driver_payout_cents)::bigint, count(*)::int
  from public.kolis_parcels p
  join public.drivers d on d.id = p.driver_id
  left join public.kolis_driver_payout dp on dp.driver_id = p.driver_id
  where p.status = 'delivered' and p.driver_paid_at is null and p.driver_payout_cents is not null
    and p.carrier_org_id is null                       -- fleet parcels pay via statements
    and exists (select 1 from public.drivers a where a.id = auth.uid() and a.is_admin)
  group by p.driver_id, d.full_name, dp.interac_email
  order by sum(p.driver_payout_cents) desc;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_pickup_zones()
 RETURNS TABLE(id text, name text, region text, address text, latitude double precision, longitude double precision)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select id, name, region, address, latitude, longitude
  from public.zones
  where is_active = true and latitude is not null and longitude is not null
  order by region, name;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_prospect_add(p_name text, p_category text, p_tier integer, p_contact text, p_email text, p_phone text, p_address text, p_city text, p_summary text DEFAULT NULL::text, p_turnover text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if not coalesce(public.kolis_is_staff(), false) then raise exception 'forbidden'; end if;
  insert into public.concord_outreach(business_name, category, tier, contact_name, email, phone, address, city, summary, turnover, stage)
    values (p_name, nullif(trim(p_category),''), p_tier, nullif(trim(p_contact),''),
            nullif(lower(trim(p_email)),''), nullif(trim(p_phone),''), nullif(trim(p_address),''),
            nullif(trim(p_city),''), nullif(trim(p_summary),''), nullif(trim(p_turnover),''), 'to_prospect')
  returning id into v_id;
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_prospect_events(p_id uuid)
 RETURNS TABLE(type text, link text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not coalesce(public.kolis_is_staff(), false) then raise exception 'forbidden'; end if;
  return query
    select e.type, e.link, e.created_at from public.concord_outreach_events e
    where e.email = (select email from public.concord_outreach where id = p_id)
    order by e.created_at desc;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_prospect_get(p_id uuid)
 RETURNS TABLE(id uuid, business_name text, category text, tier integer, contact_name text, email text, phone text, address text, city text, summary text, turnover text, stage text, letter_url text, letter_downloaded_at timestamp with time zone, contacted_at timestamp with time zone, followup_due_at timestamp with time zone, followup_sent_at timestamp with time zone, opened_at timestamp with time zone, clicked_at timestamp with time zone, notes text, opens bigint, clicks bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not coalesce(public.kolis_is_staff(), false) then raise exception 'forbidden'; end if;
  return query
    select o.id, o.business_name, o.category, o.tier, o.contact_name, o.email, o.phone, o.address, o.city,
      o.summary, o.turnover, o.stage, o.letter_url, o.letter_downloaded_at, o.contacted_at, o.followup_due_at,
      o.followup_sent_at, o.opened_at, o.clicked_at, o.notes,
      (select count(*) from public.concord_outreach_events e where e.email = o.email and e.type = 'opened'),
      (select count(*) from public.concord_outreach_events e where e.email = o.email and e.type = 'clicked')
    from public.concord_outreach o where o.id = p_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_prospect_mark_contacted(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_email text;
begin
  if not coalesce(public.kolis_is_staff(), false) then raise exception 'forbidden'; end if;
  select email into v_email from public.concord_outreach where id = p_id;
  update public.concord_outreach set
    contacted_at = coalesce(contacted_at, now()),
    stage = 'met',
    followup_due_at = case when v_email is not null then public.kolis_next_business_day(now() + interval '2 days') else null end
   where id = p_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_prospect_mark_downloaded(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not coalesce(public.kolis_is_staff(), false) then raise exception 'forbidden'; end if;
  update public.concord_outreach
    set letter_downloaded_at = coalesce(letter_downloaded_at, now()),
        stage = case when stage = 'to_prospect' then 'pending' else stage end
   where id = p_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_prospect_set_stage(p_id uuid, p_stage text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not coalesce(public.kolis_is_staff(), false) then raise exception 'forbidden'; end if;
  if p_stage not in ('to_prospect','pending','met','replied','won','lost') then raise exception 'bad stage'; end if;
  update public.concord_outreach set stage = p_stage,
    followup_due_at = case when p_stage in ('replied','won','lost') then null else followup_due_at end
   where id = p_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_prospect_update(p_id uuid, p_contact text, p_email text, p_phone text, p_address text, p_city text, p_notes text, p_summary text DEFAULT NULL::text, p_turnover text DEFAULT NULL::text, p_letter_url text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_old_email text; v_stage text; v_due timestamptz; v_new_email text;
begin
  if not coalesce(public.kolis_is_staff(), false) then raise exception 'forbidden'; end if;
  select email, stage, followup_due_at into v_old_email, v_stage, v_due from public.concord_outreach where id = p_id;
  v_new_email := nullif(lower(trim(p_email)), '');
  update public.concord_outreach set
    contact_name = coalesce(nullif(trim(p_contact),''), contact_name),
    email        = coalesce(v_new_email, email),
    phone        = coalesce(nullif(trim(p_phone),''), phone),
    address      = coalesce(nullif(trim(p_address),''), address),
    city         = coalesce(nullif(trim(p_city),''), city),
    summary      = coalesce(nullif(trim(p_summary),''), summary),
    turnover     = coalesce(nullif(trim(p_turnover),''), turnover),
    notes        = coalesce(nullif(trim(p_notes),''), notes),
    letter_url   = coalesce(nullif(trim(p_letter_url),''), letter_url)
   where id = p_id;
  if v_old_email is null and v_new_email is not null and v_stage = 'met' and v_due is null then
    update public.concord_outreach set followup_due_at = public.kolis_next_business_day(now() + interval '2 days')
      where id = p_id;
  end if;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_prospects_list(p_filter text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, business_name text, category text, tier integer, contact_name text, email text, phone text, address text, city text, summary text, turnover text, stage text, letter_url text, letter_downloaded_at timestamp with time zone, contacted_at timestamp with time zone, followup_due_at timestamp with time zone, followup_sent_at timestamp with time zone, opened_at timestamp with time zone, clicked_at timestamp with time zone, notes text, opens bigint, clicks bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not coalesce(public.kolis_is_staff(), false) then raise exception 'forbidden'; end if;
  return query
    select o.id, o.business_name, o.category, o.tier, o.contact_name, o.email, o.phone, o.address, o.city,
      o.summary, o.turnover, o.stage, o.letter_url, o.letter_downloaded_at, o.contacted_at, o.followup_due_at,
      o.followup_sent_at, o.opened_at, o.clicked_at, o.notes,
      (select count(*) from public.concord_outreach_events e where e.email = o.email and e.type = 'opened'),
      (select count(*) from public.concord_outreach_events e where e.email = o.email and e.type = 'clicked')
    from public.concord_outreach o
    where p_filter is null
       or (p_filter = 'needs_email' and o.email is null and o.stage <> 'to_prospect')
       or (p_filter like 'tier%' and o.tier = nullif(substring(p_filter from 5), '')::int)
       or (p_filter = o.stage)
    order by o.tier nulls last, o.created_at;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_region_code(p_city text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select translate(lower((regexp_split_to_array(coalesce(trim(p_city),''), '\s+'))[1]),
                   'áàâäéèêëíìîïóòôöúùûüç','aaaaeeeeiiiioooouuuuc');
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_report_location(p_lat double precision, p_lng double precision)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into public.kolis_driver_locations(kolis_id, lat, lng, updated_at)
  values (auth.uid(), p_lat, p_lng, now())
  on conflict (kolis_id) do update set lat = excluded.lat, lng = excluded.lng, updated_at = now();
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_request_contact_update(p_email text, p_phone text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_email text; v_phone text;
begin
  if auth.uid() is null then raise exception 'unauthorized'; end if;
  p_email := nullif(trim(lower(coalesce(p_email, ''))), '');
  p_phone := nullif(regexp_replace(coalesce(p_phone, ''), '[^0-9+]', '', 'g'), '');
  if p_email is null and p_phone is null then raise exception 'nothing_to_update'; end if;
  select email, phone into v_email, v_phone from public.kolis_profiles where id = auth.uid();
  delete from public.kolis_contact_requests where user_id = auth.uid() and status = 'pending'; -- one open request per user
  insert into public.kolis_contact_requests(user_id, current_email, current_phone, requested_email, requested_phone)
  values (auth.uid(), v_email, v_phone, p_email, p_phone) returning id into v_id;
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_route_km(p_from text, p_to text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare a text; b text; k text;
begin
  a := public.kolis_region_code(p_from); b := public.kolis_region_code(p_to);
  if a is null or b is null or a = '' or b = '' or a = b then return 30; end if;
  k := case when a < b then a || '-' || b else b || '-' || a end;
  return case k
    when 'montreal-ottawa' then 200 when 'kingston-ottawa' then 195 when 'ottawa-toronto' then 450
    when 'gatineau-ottawa' then 20  when 'ottawa-quebec' then 480 when 'ottawa-trois-rivieres' then 360
    when 'ottawa-sherbrooke' then 380 when 'chicoutimi-ottawa' then 660 when 'moncton-ottawa' then 1100
    when 'montreal-quebec' then 250 when 'montreal-trois-rivieres' then 140 when 'montreal-toronto' then 540
    when 'kingston-montreal' then 290 when 'gatineau-montreal' then 200 when 'montreal-sherbrooke' then 150
    when 'chicoutimi-montreal' then 460 when 'moncton-montreal' then 1100
    when 'quebec-trois-rivieres' then 130 when 'chicoutimi-quebec' then 210 when 'quebec-sherbrooke' then 240
    when 'kingston-toronto' then 260
    else 250 end;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_shopify_provision(p_shop text, p_name text, p_owner_user uuid, p_email text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_org uuid;
begin
  select org_id into v_org from public.kolis_shopify_shops where shop_domain = lower(p_shop);
  if v_org is null then
    insert into public.kolis_orgs(name, type, status, kyb_status, brand_name)
      values (coalesce(nullif(trim(p_name), ''), p_shop), 'shipper', 'active', 'pending', nullif(trim(p_name), ''))
      returning id into v_org;
    update public.kolis_shopify_shops set org_id = v_org where shop_domain = lower(p_shop);
  end if;
  -- Backfill the owner whenever we have one and the org still has no owner.
  if p_owner_user is not null then
    insert into public.kolis_profiles(id, email, full_name, role, country, identity_verified, verification_fee_paid)
      values (p_owner_user, lower(coalesce(p_email, '')), p_name, 'sender', 'CA', false, false)
      on conflict (id) do update set email = coalesce(public.kolis_profiles.email, excluded.email);
    if not exists (select 1 from public.kolis_org_members where org_id = v_org and role = 'owner') then
      insert into public.kolis_org_members(org_id, user_id, role) values (v_org, p_owner_user, 'owner') on conflict do nothing;
    end if;
  end if;
  return v_org;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_sync_zone_to_hub()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    update public.kolis_hubs set is_active = false where zone_id = old.id;
    return old;
  end if;
  insert into public.kolis_hubs (zone_id, city, name, address, latitude, longitude, is_active)
  values (new.id, public.kolis_zone_city(new.region), new.name, new.address,
          new.latitude, new.longitude, coalesce(new.is_active, true))
  on conflict (zone_id) do update set
    city      = excluded.city,
    name      = excluded.name,
    address   = excluded.address,
    latitude  = excluded.latitude,
    longitude = excluded.longitude,
    is_active = excluded.is_active;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_tax_rate(p_country text, p_province text)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select rate from public.kolis_tax_config where country = p_country and province = upper(coalesce(p_province,'ON'))),
    (select rate from public.kolis_tax_config where country = p_country and province is null),
    0);
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_tax_years()
 RETURNS TABLE(year integer, total_payout_cents bigint, parcels integer)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select extract(year from coalesce(p.delivered_at, p.created_at))::int as year,
         sum(coalesce(p.driver_payout_cents, 0))::bigint as total_payout_cents,
         count(*)::int as parcels
  from public.kolis_parcels p
  where p.driver_id = auth.uid() and p.status = 'delivered'
  group by 1
  order by 1 desc;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_track(p_code text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when p.id is null then null else jsonb_build_object(
    'code', p.code, 'status', p.status, 'dropoff_type', p.dropoff_type,
    'from_city', p.from_city, 'to_city', p.to_city, 'created_at', p.created_at, 'delivered_at', p.delivered_at,
    'courier', case when p.status in ('picked_up','in_transit','dispatched','delivered')
                    then nullif(split_part(coalesce(d.full_name, p.external_driver_name, ''), ' ', 1), '') end,
    'brand', case when o.id is not null and coalesce(o.brand_tracking, true) then
               jsonb_build_object('name', coalesce(o.brand_name, o.name), 'logo', o.brand_logo_url,
                                  'color', o.brand_color, 'powered_by', coalesce(o.brand_powered_by, true)) end
  ) end
  from (select * from public.kolis_parcels where upper(code) = upper(trim(p_code)) limit 1) p
  left join public.drivers d on d.id = p.driver_id
  left join public.kolis_orgs o on o.id = p.org_id;
$function$
;

CREATE OR REPLACE FUNCTION public.kolis_track_by_code(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v record;
  v_lat double precision; v_lng double precision; v_at timestamptz;
  v_dest_lat double precision; v_dest_lng double precision;
  v_dist_km double precision; v_eta_min int;
  v_name text; v_first text;
begin
  select * into v from public.kolis_parcels where code = p_code;
  if not found then return null; end if;

  if v.driver_id is not null then
    if coalesce(v.accepted_via,'') = 'kolis' then
      select lat, lng, updated_at into v_lat, v_lng, v_at
      from public.kolis_driver_locations where kolis_id = v.driver_id;
    end if;
    -- Fallback (and default for LoadQ-accepted): the LoadQ driver's live GPS.
    if v_lat is null then
      select d.current_lat, d.current_lng, d.location_at into v_lat, v_lng, v_at
      from public.drivers d
      where d.id = coalesce((select loadq_driver_id from public.kolis_profiles where id = v.driver_id), v.driver_id);
    end if;
    select coalesce(nullif(btrim(dd.full_name),''), pr.full_name) into v_name
    from public.kolis_profiles pr
    left join public.drivers dd on dd.id = coalesce(pr.loadq_driver_id, pr.id)
    where pr.id = v.driver_id;
    v_first := nullif(split_part(coalesce(v_name,''), ' ', 1), '');
  end if;

  -- destination coords: the parcel's actual geocoded drop-off first, else a zone in the region
  v_dest_lat := v.dropoff_lat; v_dest_lng := v.dropoff_lng;
  if v_dest_lat is null or v_dest_lng is null then
    select latitude, longitude into v_dest_lat, v_dest_lng
    from public.zones where region = v.to_region and latitude is not null limit 1;
  end if;

  if v_lat is not null and v_dest_lat is not null then
    v_dist_km := 6371 * acos(least(1, greatest(-1,
      cos(radians(v_lat)) * cos(radians(v_dest_lat)) * cos(radians(v_dest_lng) - radians(v_lng))
      + sin(radians(v_lat)) * sin(radians(v_dest_lat)))));
    v_eta_min := round((v_dist_km / 80.0) * 60);  -- ~80 km/h average
  end if;

  return jsonb_build_object(
    'code', v.code,
    'status', v.status,
    'dropoff_type', v.dropoff_type,
    'from_city', v.from_city,
    'to_city', v.to_city,
    'driver_first_name', v_first,
    'driver_lat', v_lat, 'driver_lng', v_lng, 'driver_updated_at', v_at,
    'dest_lat', v_dest_lat, 'dest_lng', v_dest_lng,
    'distance_km', round(v_dist_km::numeric, 1), 'eta_minutes', v_eta_min,
    'stale', (v_at is null or v_at < now() - interval '10 minutes')
  );
end; $function$
;

CREATE OR REPLACE FUNCTION public.kolis_zone_city(p_region text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case lower(coalesce(p_region,''))
    when 'gatineau' then 'Gatineau' when 'montreal' then 'Montréal'
    when 'ottawa' then 'Ottawa'     when 'quebec'   then 'Québec'
    when 'toronto' then 'Toronto'
    else initcap(coalesce(p_region,'')) end;
$function$
;


-- ============================================================================
-- 5. VIEWS
-- ============================================================================
create or replace view public.kolis_parcels_for_drivers as  SELECT id,
    code,
    status,
    dropoff_type,
    size,
    from_city,
    to_city,
    pickup_zone,
    pickup_hub,
    dropoff_zone,
    dropoff_addr,
    price_cents,
    driver_id,
    delivery_code,
    created_at
   FROM kolis_parcels;


-- ============================================================================
-- 6. INDEXES (non-constraint-backing)
-- ============================================================================
CREATE INDEX concord_outreach_events_email_idx ON public.concord_outreach_events USING btree (email);
CREATE INDEX idx_kolis_org_clients_org ON public.kolis_org_clients USING btree (org_id);
CREATE INDEX kolis_bulk_drafts_org ON public.kolis_bulk_drafts USING btree (org_id, updated_at DESC);
CREATE INDEX kolis_contact_requests_pending ON public.kolis_contact_requests USING btree (status) WHERE (status = 'pending'::text);
CREATE UNIQUE INDEX kolis_hubs_zone_id ON public.kolis_hubs USING btree (zone_id);
CREATE INDEX kolis_invoice_lines_inv ON public.kolis_invoice_lines USING btree (invoice_id);
CREATE INDEX kolis_notifications_state_idx ON public.kolis_notifications USING btree (state) WHERE (state <> 'sent'::text);
CREATE INDEX kolis_org_addresses_org ON public.kolis_org_addresses USING btree (org_id);
CREATE UNIQUE INDEX kolis_org_invites_org_email ON public.kolis_org_invites USING btree (org_id, lower(email));
CREATE INDEX kolis_parcels_billable ON public.kolis_parcels USING btree (org_id) WHERE ((billing_mode = 'invoice'::text) AND (status = 'delivered'::text) AND (billed_invoice_id IS NULL));
CREATE INDEX kolis_parcels_carrier_org_id ON public.kolis_parcels USING btree (carrier_org_id);
CREATE INDEX kolis_parcels_client_idx ON public.kolis_parcels USING btree (client_id);
CREATE INDEX kolis_parcels_fleet_unpaid ON public.kolis_parcels USING btree (carrier_org_id) WHERE ((status = 'delivered'::text) AND (driver_paid_at IS NULL) AND (paid_statement_id IS NULL));
CREATE UNIQUE INDEX kolis_parcels_org_client_ref ON public.kolis_parcels USING btree (org_id, client_ref) WHERE (client_ref IS NOT NULL);
CREATE INDEX kolis_parcels_org_id ON public.kolis_parcels USING btree (org_id);
CREATE INDEX kolis_parcels_paid_statement ON public.kolis_parcels USING btree (paid_statement_id);
CREATE INDEX kolis_payout_lines_stmt ON public.kolis_payout_statement_lines USING btree (statement_id);
CREATE UNIQUE INDEX kolis_tax_config_key ON public.kolis_tax_config USING btree (country, COALESCE(province, '*'::text));
CREATE INDEX kolis_webhook_deliveries_due ON public.kolis_webhook_deliveries USING btree (next_attempt_at) WHERE (status = 'pending'::text);


