alter table public.kolis_parcels add constraint kolis_parcels_sender_id_fkey FOREIGN KEY (sender_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.kolis_payout_statement_lines add constraint kolis_payout_statement_lines_statement_id_fkey FOREIGN KEY (statement_id) REFERENCES kolis_payout_statements(id) ON DELETE CASCADE;
alter table public.kolis_payout_statements add constraint kolis_payout_statements_org_id_fkey FOREIGN KEY (org_id) REFERENCES kolis_orgs(id) ON DELETE CASCADE;
alter table public.kolis_profiles add constraint kolis_profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.kolis_profiles add constraint kolis_profiles_loadq_driver_id_fkey FOREIGN KEY (loadq_driver_id) REFERENCES drivers(id);
alter table public.kolis_shopify_shops add constraint kolis_shopify_shops_org_id_fkey FOREIGN KEY (org_id) REFERENCES kolis_orgs(id);
alter table public.kolis_webhook_deliveries add constraint kolis_webhook_deliveries_endpoint_id_fkey FOREIGN KEY (endpoint_id) REFERENCES kolis_webhook_endpoints(id) ON DELETE CASCADE;
alter table public.kolis_webhook_endpoints add constraint kolis_webhook_endpoints_org_id_fkey FOREIGN KEY (org_id) REFERENCES kolis_orgs(id) ON DELETE CASCADE;
alter table public.kolis_zone_settings add constraint kolis_zone_settings_zone_id_fkey FOREIGN KEY (zone_id) REFERENCES zones(id) ON DELETE CASCADE;


-- ============================================================================
-- 8. TRIGGERS
-- ============================================================================
CREATE TRIGGER kolis_new_parcel_alert AFTER INSERT ON public.kolis_parcels FOR EACH ROW EXECUTE FUNCTION kolis_notify_new_parcel();
CREATE TRIGGER kolis_parcels_geocode AFTER INSERT ON public.kolis_parcels FOR EACH ROW EXECUTE FUNCTION kolis_geocode_trg();
CREATE TRIGGER kolis_parcels_guard_trg BEFORE INSERT OR UPDATE ON public.kolis_parcels FOR EACH ROW EXECUTE FUNCTION kolis_parcels_guard();
CREATE TRIGGER kolis_parcels_notify_created AFTER INSERT ON public.kolis_parcels FOR EACH ROW EXECUTE FUNCTION kolis_notify_recipient_created_trg();
CREATE TRIGGER kolis_parcels_notify_recipient AFTER INSERT OR UPDATE OF status ON public.kolis_parcels FOR EACH ROW EXECUTE FUNCTION kolis_notify_recipient_trg();
CREATE TRIGGER kolis_parcels_webhook_trg AFTER INSERT OR UPDATE ON public.kolis_parcels FOR EACH ROW EXECUTE FUNCTION kolis_enqueue_webhooks();
CREATE TRIGGER trg_kolis_parcels_set_region BEFORE INSERT OR UPDATE OF to_city, to_region ON public.kolis_parcels FOR EACH ROW EXECUTE FUNCTION kolis_parcels_set_region();


