-- 9. ROW LEVEL SECURITY (enable + policies)
-- NOTE: several policies reference the LoadQ-owned `drivers` table (cross-app).
-- ============================================================================
alter table public.kolis_access_keys enable row level security;
alter table public.kolis_admin_invites enable row level security;
alter table public.kolis_admin_roles enable row level security;
alter table public.kolis_bulk_drafts enable row level security;
alter table public.kolis_call_requests enable row level security;
alter table public.kolis_claims enable row level security;
alter table public.kolis_contact_requests enable row level security;
alter table public.kolis_driver_locations enable row level security;
alter table public.kolis_driver_payout enable row level security;
alter table public.kolis_email_otp enable row level security;
alter table public.kolis_founding enable row level security;
alter table public.kolis_freight_requests enable row level security;
alter table public.kolis_hubs enable row level security;
alter table public.kolis_invoice_lines enable row level security;
alter table public.kolis_invoices enable row level security;
alter table public.kolis_org_addresses enable row level security;
alter table public.kolis_org_clients enable row level security;
alter table public.kolis_org_invites enable row level security;
alter table public.kolis_org_members enable row level security;
alter table public.kolis_orgs enable row level security;
alter table public.kolis_parcels enable row level security;
alter table public.kolis_payout_statement_lines enable row level security;
alter table public.kolis_payout_statements enable row level security;
alter table public.kolis_profiles enable row level security;
alter table public.kolis_shopify_shops enable row level security;
alter table public.kolis_webhook_deliveries enable row level security;
alter table public.kolis_webhook_endpoints enable row level security;
alter table public.kolis_zone_settings enable row level security;

create policy "kolis_call_requests_staff_read" on public.kolis_call_requests as permissive for select to authenticated using (kolis_is_staff());
create policy "kolis_driver_loc_self" on public.kolis_driver_locations as permissive for all to authenticated using ((kolis_id = auth.uid())) with check ((kolis_id = auth.uid()));
create policy "kdp_admin_select" on public.kolis_driver_payout as permissive for select to public using ((EXISTS ( SELECT 1
   FROM drivers a
  WHERE ((a.id = auth.uid()) AND a.is_admin))));
create policy "kdp_self_insert" on public.kolis_driver_payout as permissive for insert to public with check ((auth.uid() = driver_id));
create policy "kdp_self_select" on public.kolis_driver_payout as permissive for select to public using ((auth.uid() = driver_id));
create policy "kdp_self_update" on public.kolis_driver_payout as permissive for update to public using ((auth.uid() = driver_id));
create policy "kolis_freight_staff_read" on public.kolis_freight_requests as permissive for select to authenticated using (kolis_is_staff());
create policy "kolis_hubs_admin_all" on public.kolis_hubs as permissive for all to public using ((EXISTS ( SELECT 1
   FROM drivers d
  WHERE ((d.id = auth.uid()) AND d.is_admin)))) with check ((EXISTS ( SELECT 1
   FROM drivers d
  WHERE ((d.id = auth.uid()) AND d.is_admin))));
create policy "kolis_hubs_read" on public.kolis_hubs as permissive for select to public using (true);
create policy "kolis_parcels_admin_all" on public.kolis_parcels as permissive for all to public using ((EXISTS ( SELECT 1
   FROM drivers d
  WHERE ((d.id = auth.uid()) AND d.is_admin)))) with check ((EXISTS ( SELECT 1
   FROM drivers d
  WHERE ((d.id = auth.uid()) AND d.is_admin))));
create policy "kolis_parcels_driver_select" on public.kolis_parcels as permissive for select to public using ((auth.uid() = driver_id));
create policy "kolis_parcels_driver_update" on public.kolis_parcels as permissive for update to public using ((auth.uid() = driver_id));
create policy "kolis_parcels_org_select" on public.kolis_parcels as permissive for select to public using (((org_id IS NOT NULL) AND (COALESCE(kolis_org_role(org_id), ''::text) <> ''::text)));
create policy "kolis_parcels_sender_insert" on public.kolis_parcels as permissive for insert to public with check ((auth.uid() = sender_id));
create policy "kolis_parcels_sender_select" on public.kolis_parcels as permissive for select to public using ((auth.uid() = sender_id));
create policy "kolis_parcels_sender_update" on public.kolis_parcels as permissive for update to public using ((auth.uid() = sender_id));
create policy "kolis_profiles_self_ins" on public.kolis_profiles as permissive for insert to public with check ((auth.uid() = id));
create policy "kolis_profiles_self_sel" on public.kolis_profiles as permissive for select to public using ((auth.uid() = id));
create policy "kolis_profiles_self_upd" on public.kolis_profiles as permissive for update to public using ((auth.uid() = id));
create policy "kolis_zone_settings_admin_all" on public.kolis_zone_settings as permissive for all to public using ((EXISTS ( SELECT 1
   FROM drivers d
  WHERE ((d.id = auth.uid()) AND d.is_admin)))) with check ((EXISTS ( SELECT 1
   FROM drivers d
  WHERE ((d.id = auth.uid()) AND d.is_admin))));
create policy "kolis_zone_settings_read" on public.kolis_zone_settings as permissive for select to public using (true);


